// --- the farm palette ------------------------------------------------------

// The farm's own colours, on top of the engine's 24. They are organised the
// same way `crate::palette` is: each material owns a short ramp — a shadow, a
// base and a highlight — and a drawing routine stays inside one ramp. A new
// colour here should mean a new material, not a one-off tint for one sprite.
// The public ones below are part of the art contract: a colour a game can name.
//
// Opaque colour shorthand, as in `crate::palette`.
const fn c(r: u8, g: u8, b: u8) -> Color8 {
    Color8::new(r, g, b, 255)
}

