// --- one atlas -------------------------------------------------------------

/// One atlas: the file stem it is written under and the sprites inside it.
pub struct Sheet {
    /// File stem. The sheet is written as `<stem>.png` and `<stem>.json`.
    pub stem: &'static str,
    /// The sprites, in authoring order. Packing reorders them; the names do not
    /// change.
    pub sprites: Vec<(String, Image)>,
}

/// The five atlases, in write order.
#[must_use]
pub fn sheets() -> Vec<Sheet> {
    vec![
        Sheet {
            stem: "terrain",
            sprites: terrain_sprites(),
        },
        Sheet {
            stem: "crops",
            sprites: crop_sprites(),
        },
        Sheet {
            stem: "props",
            sprites: prop_sprites(),
        },
        Sheet {
            stem: "characters",
            sprites: character_sprites(),
        },
        Sheet {
            stem: "ui",
            sprites: ui_sprites(),
        },
    ]
}

/// Packs one sheet into an atlas.
///
/// The packer sorts by height and then by name, so the layout depends only on
/// the set of sprites and never on the order they were built in.
pub fn atlas(sheet: &Sheet) -> Result<Atlas> {
    Atlas::build(sheet.sprites.clone(), PADDING, MAX_SIZE)
        .map_err(|error| Error::invalid(format!("the {} atlas", sheet.stem), error.to_string()))
}

/// What `farm` wrote.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Summary {
    /// Files written (or rewritten).
    pub written: usize,
    /// Files left alone because their bytes already matched.
    pub skipped: usize,
    /// Total bytes of the generated set.
    pub bytes: usize,
}

impl Summary {
    /// The one-line report the command prints.
    #[must_use]
    pub fn line(&self, out: &Path) -> String {
        format!(
            "noxel-gen: farm {} written, {} skipped, {} bytes -> {}",
            self.written,
            self.skipped,
            self.bytes,
            out.join("farm").display()
        )
    }
}

/// Writes every farm atlas plus the contact sheet into `<out>/farm/`.
///
/// A file whose bytes already match is left untouched, which is what makes a
/// second run a no-op down to the timestamps. Every pixel is checked against
/// [`PALETTE`] before anything is written: a sprite that reached for a colour
/// outside the palette is a generation failure, not a slightly wrong PNG.
pub fn write(out: &Path, scale: u32) -> Result<Summary> {
    let dir = out.join("farm");
    let mut files: Vec<(String, Vec<u8>)> = Vec::new();

    for sheet in sheets() {
        for (name, image) in &sheet.sprites {
            check_palette(&format!("{}/{name}", sheet.stem), image)?;
        }
        let atlas = atlas(&sheet)?;
        files.push((
            format!("{}.png", sheet.stem),
            atlas.texture().image().to_png_bytes(),
        ));
        files.push((format!("{}.json", sheet.stem), json_bytes(&atlas.to_json())));
    }

    let preview = farm_preview::sheet(scale);
    check_palette("preview", &preview)?;
    files.push(("preview.png".to_string(), preview.to_png_bytes()));

    let mut summary = Summary::default();
    for (name, bytes) in &files {
        summary.bytes += bytes.len();
        let path = dir.join(name);
        if std::fs::read(&path).is_ok_and(|existing| existing == *bytes) {
            summary.skipped += 1;
            continue;
        }
        Error::write(&path, "a farm asset", bytes)?;
        summary.written += 1;
    }
    Ok(summary)
}

/// Rejects any pixel outside [`PALETTE`], and any pixel that is neither fully
/// opaque nor fully clear.
fn check_palette(what: &str, image: &Image) -> Result<()> {
    for pixel in &image.pixels {
        if pixel.a != 0 && pixel.a != 255 {
            return Err(Error::invalid(
                what,
                format!("pixel {pixel:?} is partially transparent; pixel art here is hard-edged"),
            ));
        }
        if !in_palette(*pixel) {
            return Err(Error::invalid(
                what,
                format!(
                    "pixel {pixel:?} is outside the {}-colour farm palette",
                    PALETTE.len()
                ),
            ));
        }
    }
    Ok(())
}

/// Renders JSON the way every text asset in the tree is written: two-space
/// indentation and a trailing newline.
fn json_bytes(value: &JsonValue) -> Vec<u8> {
    let mut text = value.to_string_pretty();
    text.push('\n');
    text.into_bytes()
}

// --- drawing helpers -------------------------------------------------------

/// Fills an inclusive rectangle, clipped to the image.
fn rect(img: &mut Image, x0: i32, y0: i32, x1: i32, y1: i32, color: Color8) {
    draw::fill(img, Area::new(x0, y0, x1, y1), color);
}

/// A filled ellipse, by the integer inequality `dx²·ry² + dy²·rx² <= rx²·ry²`.
///
/// Integer on purpose: an ellipse drawn from floats is a rounding decision per
/// pixel, and a rounding decision is a place where two machines can disagree.
fn oval(img: &mut Image, cx: i32, cy: i32, rx: i32, ry: i32, color: Color8) {
    for dy in -ry..=ry {
        for dx in -rx..=rx {
            if dx * dx * ry * ry + dy * dy * rx * rx <= rx * rx * ry * ry {
                draw::put(img, cx + dx, cy + dy, color);
            }
        }
    }
}

/// A filled circle.
fn disc(img: &mut Image, cx: i32, cy: i32, r: i32, color: Color8) {
    oval(img, cx, cy, r, r, color);
}

/// Clears the pixels outside a rounded rectangle's corners.
///
/// The cut is a quarter circle tested in integers, so a corner is either there
/// or it is not; there is no half-covered pixel and so nothing to antialias.
fn round(img: &mut Image, x0: i32, y0: i32, x1: i32, y1: i32, r: i32) {
    for dy in 0..r {
        for dx in 0..r {
            if (r - dx) * (r - dx) + (r - dy) * (r - dy) <= r * r {
                continue;
            }
            draw::clear(img, x0 + dx, y0 + dy);
            draw::clear(img, x1 - dx, y0 + dy);
            draw::clear(img, x0 + dx, y1 - dy);
            draw::clear(img, x1 - dx, y1 - dy);
        }
    }
}

/// A lit plank: a horizontal board with a highlight along its top edge and a
/// dark seam under it. Boards are what most of this module's carpentry is made
/// of, so the three lines live in one place.
fn plank(img: &mut Image, x0: i32, x1: i32, y: i32, base: Color8, light: Color8, shade: Color8) {
    draw::hline(img, x0, x1, y, base);
    draw::hline(img, x0, x1, y - 1, light);
    draw::hline(img, x0, x1, y + 1, shade);
}

/// Finishes a free-standing sprite with the house outline.
fn finish(img: &mut Image) {
    draw::outline(img, SHADOW);
}

// --- terrain ---------------------------------------------------------------

/// The fourteen ground tiles, in sheet order.
fn terrain_sprites() -> Vec<(String, Image)> {
    TERRAIN_NAMES
        .iter()
        .filter_map(|name| ground(name).map(|image| ((*name).to_string(), image)))
        .collect()
}

/// One ground tile by name.
#[must_use]
pub fn ground(name: &str) -> Option<Image> {
    let image = match name {
        "grass" => meadow(GRASS_MID, GRASS_DARK, GRASS_LIGHT, GRASS_SEED),
        "grass_dark" => meadow(GRASS_DARK, LEAF_DARK, GRASS_MID, MEADOW_SEED),
        "grass_flower" => meadow_flowers(),
        "grass_tuft" => meadow_tuft(),
        "dirt" => dirt_field(),
        "tilled" => furrows(TILLED_DARK, TILLED_MID, TILLED_LIGHT, false),
        "watered" => furrows(WATERED_DARK, WATERED_MID, WATERED_LIGHT, true),
        "path" => path_field(true),
        "path_worn" => path_field(false),
        "stone" => cobbles(),
        "water" => water_field(),
        "sand" => sand_field(),
        "weed" => weed(),
        "stump_ground" => stump_ground(),
        _ => return None,
    };
    Some(image)
}

/// A meadow: a periodic tone field with a scatter of blades over it.
///
/// Both noise octaves wrap at [`TILE`] (sixteen pixels is eight cells of the
/// half-speed sample and four of the quarter-speed one, and both lattice
/// periods divide that), and the blades are placed off the tile's edge, so the
/// tile repeats without a seam. There is deliberately no border lighting: a lit
/// top row would be a grid line across a field of these.
fn meadow(base: Color8, shade: Color8, light: Color8, seed: u64) -> Image {
    let mut img = Image::from_fn(TILE, TILE, |x, y| {
        let (fx, fy) = (x as f32, y as f32);
        let tone = tileable_value_2d(fx * 0.5, fy * 0.5, 8, seed);
        let patch = tileable_value_2d(fx * 0.25, fy * 0.5, 4, seed ^ 0x51ED);
        if tone > 0.44 || patch > 0.62 {
            light
        } else if tone < -0.36 {
            shade
        } else {
            base
        }
    });
    for i in 0..6 {
        let x = 2 + (draw::hash01(i, 1, seed) * 11.0) as i32;
        let y = 5 + (draw::hash01(i, 2, seed) * 9.0) as i32;
        draw::blade(&mut img, x, y, 2, shade, light);
        if draw::hash01(i, 3, seed) < 0.5 {
            draw::put(&mut img, x + 1, y, base);
        }
    }
    img
}

/// Meadow grass with three small flowers in it: one red, one blue, one yellow.
fn meadow_flowers() -> Image {
    let mut img = meadow(GRASS_MID, GRASS_DARK, GRASS_LIGHT, GRASS_SEED);
    let flowers = [
        (3, 4, ROOF_RED, ROOF_LIGHT),
        (10, 6, BLUE_MID, BLUE_LIGHT),
        (6, 12, CORN_MID, CORN_LIGHT),
    ];
    for (x, y, petal, light) in flowers {
        draw::put(&mut img, x, y - 1, petal);
        draw::put(&mut img, x - 1, y, petal);
        draw::put(&mut img, x + 1, y, light);
        draw::put(&mut img, x, y + 1, petal);
        draw::put(&mut img, x + 1, y - 1, light);
        draw::put(&mut img, x, y, SAND_LIGHT);
        draw::put(&mut img, x, y + 2, GRASS_DARK);
    }
    img
}

/// Meadow grass with a tall clump of blades: the tile you walk past and read as
/// "there is something in this grass".
fn meadow_tuft() -> Image {
    let mut img = meadow(GRASS_MID, GRASS_DARK, GRASS_LIGHT, GRASS_SEED);
    // The clump: seven blades of different heights, leaning outward, each with
    // a lit tip. Tall enough to read as "there is something here" without
    // looking like a crop.
    for (x, height, lean) in [
        (8, 9, 0),
        (6, 8, -1),
        (10, 7, 1),
        (4, 6, -1),
        (12, 5, 1),
        (7, 6, 0),
        (9, 5, 0),
    ] {
        draw::vline(&mut img, x, 14 - height, 13, LEAF_MID);
        draw::vline(&mut img, x + lean, 13 - height, 14 - height, GRASS_LIGHT);
        draw::put(&mut img, x, 14, LEAF_DARK);
    }
    img
}

/// Bare earth: a periodic mottle with a few pebbles turned up in it.
fn dirt_field() -> Image {
    let mut img = Image::from_fn(TILE, TILE, |x, y| {
        let (fx, fy) = (x as f32, y as f32);
        let tone = tileable_value_2d(fx * 0.5, fy * 0.5, 8, DIRT_SEED);
        if tone > 0.5 {
            DIRT_LIGHT
        } else if tone < -0.45 {
            DIRT_DARK
        } else {
            DIRT_MID
        }
    });
    for i in 0..5 {
        let x = 2 + (draw::hash01(i, 7, DIRT_SEED) * 11.0) as i32;
        let y = 2 + (draw::hash01(i, 9, DIRT_SEED) * 11.0) as i32;
        draw::put(&mut img, x, y, DIRT_LIGHT);
        draw::put(&mut img, x + 1, y, DIRT_DARK);
        draw::put(&mut img, x, y + 1, DIRT_DARK);
    }
    img
}

/// A hoed field: ridges and furrows four pixels apart.
///
/// The furrow rhythm is what makes `tilled` and `watered` read as the same
/// ground in two states, so both are drawn by this one routine with different
/// ramps. `standing` adds the glints of water sitting in the furrows, which is
/// what tells a player at a glance which tiles they have already done.
fn furrows(dark: Color8, mid: Color8, light: Color8, standing: bool) -> Image {
    let mut img = Image::new(TILE, TILE, mid);
    for y in 0..TILE as i32 {
        for x in 0..TILE as i32 {
            // A ridge, its slope, the furrow floor, and the far slope.
            let color = match y.rem_euclid(4) {
                0 => light,
                2 => dark,
                _ => mid,
            };
            img.set(x as u32, y as u32, color);
            // Clods: the ridges are broken up so the rows are not ruled lines.
            let grain = draw::hash01(x, y, DIRT_SEED);
            if y.rem_euclid(4) == 0 && grain < 0.22 {
                img.set(x as u32, y as u32, mid);
            }
            if y.rem_euclid(4) == 2 && grain > 0.80 {
                img.set(x as u32, y as u32, mid);
            }
        }
    }
    if standing {
        for i in 0..7 {
            let x = (draw::hash01(i, 3, WATERED_SEED) * 15.0) as i32;
            let y = 2 + 4 * (i % 4);
            draw::put(&mut img, x, y, WATER_SHALLOW);
            if draw::hash01(i, 5, WATERED_SEED) < 0.5 {
                draw::put(&mut img, x + 1, y, mid);
            }
        }
    }
    img
}

/// A gravel path, or — with `gravel` false — the same path trodden flat.
///
/// `path` is loose stone over dirt; `path_worn` is what it looks like a season
/// later: packed, darker, fewer stones, and grass starting at the edges.
fn path_field(gravel: bool) -> Image {
    let base = if gravel { DIRT_MID } else { DIRT_DARK };
    let mut img = Image::from_fn(TILE, TILE, |x, y| {
        let (fx, fy) = (x as f32, y as f32);
        let tone = tileable_value_2d(fx * 0.5, fy * 0.5, 8, PATH_SEED);
        if tone > 0.55 {
            if gravel { DIRT_LIGHT } else { DIRT_MID }
        } else if tone < -0.35 {
            if gravel { DIRT_DARK } else { ROAD_DARK }
        } else {
            base
        }
    });
    let stones = if gravel { 9 } else { 3 };
    for i in 0..stones {
        let x = 1 + (draw::hash01(i, 11, PATH_SEED) * 13.0) as i32;
        let y = 1 + (draw::hash01(i, 13, PATH_SEED) * 13.0) as i32;
        draw::put(&mut img, x, y, STONE_MID);
        draw::put(&mut img, x + 1, y, STONE_LIGHT);
        draw::put(&mut img, x, y + 1, ROAD_DARK);
    }
    if !gravel {
        // Grass creeping in from the edges is the whole difference between a
        // path and a worn path.
        for i in 0..4 {
            let x = 1 + (draw::hash01(i, 17, PATH_SEED) * 13.0) as i32;
            draw::put(&mut img, x, 0, GRASS_DARK);
            draw::put(&mut img, x + 1, 0, GRASS_MID);
            draw::put(&mut img, 15 - x, 15, GRASS_DARK);
        }
    }
    img
}

/// A cobbled yard: eight-by-four stones laid in a running bond.
///
/// A plain chequer of equal stones reads as graph paper however it is coloured,
/// so the courses are staggered by half a stone and each stone is shaded in
/// three steps down its height — lit top edge, body, shaded foot — which is
/// what makes the surface look laid rather than printed. Both the course height
/// and the stone width divide [`TILE`], so the bond wraps.
fn cobbles() -> Image {
    let mut img = Image::new(TILE, TILE, STONE_MID);
    for y in 0..TILE as i32 {
        let course = y.rem_euclid(4);
        let stagger = if (y / 4) % 2 == 1 { 4 } else { 0 };
        for x in 0..TILE as i32 {
            let joint = (x + stagger).rem_euclid(8);
            let color = if course == 3 || joint == 0 {
                STONE_DARK
            } else if course == 0 || (course == 1 && joint == 1) {
                STONE_MID
            } else if course == 2 {
                ROAD_DARK
            } else {
                ROAD_MID
            };
            img.set(x as u32, y as u32, color);
        }
    }
    // A scatter of worn stones, so the bond does not read as wallpaper.
    for i in 0..12 {
        let x = (draw::hash01(i, 1, STONE_SEED) * 15.0) as i32;
        let y = (draw::hash01(i, 2, STONE_SEED) * 15.0) as i32;
        let color = if draw::hash01(i, 3, STONE_SEED) < 0.5 {
            STONE_MID
        } else {
            STONE_DARK
        };
        draw::put(&mut img, x, y, color);
    }
    img
}

/// A pond: broad swells with fine ripples riding across them.
///
/// The ripple octave is sampled four times finer across than down, so a crest
/// is a wide flat band — the shape water actually makes — rather than a dot.
fn water_field() -> Image {
    Image::from_fn(TILE, TILE, |x, y| {
        let (fx, fy) = (x as f32, y as f32);
        let swell = tileable_value_2d(fx * 0.5, fy * 0.5, 8, WATER_SEED);
        let ripple = tileable_value_2d(fx * 0.25, fy * 0.5, 4, WATER_SEED ^ 0x9E37_79B9);
        let mut color = WATER_MID;
        if swell < -0.10 {
            color = WATER_DEEP;
        }
        if ripple > 0.30 {
            color = WATER_DEEP;
        }
        if ripple > 0.62 {
            color = WATER_SHALLOW;
        }
        if ripple > 0.86 && draw::hash01(x as i32, y as i32, WATER_SEED ^ 0x51ED) < 0.4 {
            color = FOAM;
        }
        color
    })
}

/// Wind-blown sand: dunes running across the tile with a lit crest.
///
/// A dune that is only one tone lighter than the sand is invisible, so the
/// crest takes [`FOAM`] and the trough [`PLASTER_DARK`], with two shells and a
/// pebble to give the eye something at one-to-one.
fn sand_field() -> Image {
    let mut img = Image::from_fn(TILE, TILE, |x, y| {
        let (fx, fy) = (x as f32, y as f32);
        let dune = tileable_value_2d(fx * 0.25, fy * 0.5, 4, SAND_SEED);
        let grain = tileable_value_2d(fx * 0.5, fy * 0.5, 8, SAND_SEED ^ 0x33);
        if dune > 0.42 {
            PLASTER_MID
        } else if dune < -0.34 || grain < -0.74 {
            PLASTER_DARK
        } else {
            SAND_LIGHT
        }
    });
    // A crest catches the light, and a shell and a pebble give the eye
    // something at one-to-one.
    draw::put(&mut img, 2, 7, FOAM);
    draw::put(&mut img, 9, 2, FOAM);
    draw::put(&mut img, 12, 12, STONE_LIGHT);
    draw::put(&mut img, 12, 13, PLASTER_DARK);
    draw::put(&mut img, 5, 12, PLASTER_DARK);
    img
}

/// A clump of weeds: fibrous blades fanning out of one root.
///
/// Weeds are the tile a player removes, so they have to be the busiest thing on
/// the ground: seven blades, each with a dark root and a lit tip.
fn weed() -> Image {
    let mut img = meadow(GRASS_MID, GRASS_DARK, GRASS_LIGHT, GRASS_SEED);
    // The clump sits in its own dark ring, which is what separates it from the
    // grass it grew out of at one-to-one.
    for (x, y) in [
        (3, 14),
        (4, 15),
        (5, 15),
        (6, 15),
        (7, 15),
        (8, 15),
        (9, 15),
        (10, 15),
        (11, 15),
        (12, 14),
        (12, 13),
        (3, 13),
    ] {
        draw::put(&mut img, x, y, LEAF_DARK);
    }
    let blades = [
        (-4, 8, -2),
        (-3, 10, -1),
        (-2, 11, -1),
        (0, 12, 0),
        (1, 11, 0),
        (3, 10, 1),
        (4, 8, 2),
        (2, 9, 1),
        (-1, 9, -1),
    ];
    for (dx, height, lean) in blades {
        let x = 8 + dx;
        let base_y = 14;
        draw::vline(&mut img, x, base_y - height, base_y - 1, LEAF_MID);
        draw::vline(
            &mut img,
            x + lean,
            base_y - height,
            base_y - height / 2,
            GRASS_LIGHT,
        );
        draw::put(&mut img, x, base_y - 1, LEAF_DARK);
    }
    // Two seed heads, so the clump has a top as well as a middle.
    draw::put(&mut img, 6, 2, STRAW_MID);
    draw::put(&mut img, 5, 3, STRAW_DARK);
    draw::put(&mut img, 10, 3, STRAW_MID);
    draw::put(&mut img, 11, 4, STRAW_DARK);
    img
}

/// The top of a felled tree, seen from above: bark ring, cut face, growth rings.
fn stump_ground() -> Image {
    let mut img = meadow(GRASS_MID, GRASS_DARK, GRASS_LIGHT, GRASS_SEED);
    disc(&mut img, 8, 8, 7, DIRT_DARK);
    disc(&mut img, 8, 8, 6, DIRT_MID);
    disc(&mut img, 8, 8, 4, DIRT_LIGHT);
    // Growth rings, then the crack that always runs out of the pith. The rings
    // are an integer annulus test, not a sampled circle: a ring drawn from
    // `sin`/`cos` picks up whatever rounding the platform's libm does.
    for dy in -7..=7 {
        for dx in -7..=7 {
            let d2 = dx * dx + dy * dy;
            let ring = (25..=36).contains(&d2) || (4..=9).contains(&d2);
            if ring {
                let x = 8 + dx;
                let y = 8 + dy;
                draw::put(&mut img, x, y, DIRT_MID);
            }
        }
    }
    draw::vline(&mut img, 8, 2, 7, DIRT_MID);
    draw::put(&mut img, 8, 6, DIRT_DARK);
    draw::hline(&mut img, 3, 6, 12, DIRT_DARK);
    draw::put(&mut img, 5, 3, DIRT_LIGHT);
    img
}

// --- crops -----------------------------------------------------------------

/// The thirty crop cells: six crops by five growth stages.
fn crop_sprites() -> Vec<(String, Image)> {
    let mut sprites = Vec::with_capacity(CROPS.len() * STAGES);
    for crop in CROPS {
        for stage in 0..STAGES {
            if let Some(image) = crop_stage(crop, stage) {
                sprites.push((format!("{crop}_{stage}"), image));
            }
        }
    }
    sprites
}

/// One crop at one growth stage, or `None` for an unknown crop or a stage past
/// the last.
#[must_use]
pub fn crop_stage(crop: &str, stage: usize) -> Option<Image> {
    if stage >= STAGES {
        return None;
    }
    let image = match crop {
        "parsnip" => parsnip(stage),
        "cauliflower" => cauliflower(stage),
        "potato" => potato(stage),
        "tomato" => tomato(stage),
        "corn" => corn(stage),
        "pumpkin" => pumpkin(stage),
        _ => return None,
    };
    Some(image)
}

/// A two-leaf sprout: what every crop looks like the day it is planted.
///
/// Stage 0 is the same shape for all six crops on purpose — a sprout carries no
/// information — but each crop then diverges immediately, so the five stages
/// read as one plant growing rather than as five unrelated sprites.
fn sprout(height: i32) -> Image {
    let mut img = Image::transparent(TILE, TILE);
    let base = 15;
    draw::vline(&mut img, 8, base - height, base, LEAF_MID);
    draw::put(&mut img, 7, base - height + 1, LEAF_MID);
    draw::put(&mut img, 6, base - height, GRASS_LIGHT);
    draw::put(&mut img, 9, base - height, LEAF_MID);
    draw::put(&mut img, 10, base - height - 1, GRASS_LIGHT);
    finish(&mut img);
    img
}

/// A leaf mass: overlapping discs, lit from the top-left and shaded into the
/// bottom-right, with a hash breaking the boundary up so it reads as leaves
/// rather than as a green boulder.
///
/// The bushier crops are all built this way — a tomato, a potato and a
/// cauliflower differ in where their mass sits and what hangs off it, not in
/// how a leaf is drawn — which is why one routine can serve all three.
fn foliage(img: &mut Image, clumps: &[(i32, i32, i32)], seed: u64) {
    for (cx, cy, r) in clumps {
        disc(img, *cx, *cy, *r, LEAF_MID);
    }
    for y in 0..TILE as i32 {
        for x in 0..TILE as i32 {
            if img.get(x as u32, y as u32) != Some(LEAF_MID) {
                continue;
            }
            let mut color = LEAF_MID;
            if (x - 5) + (y - 4) < 3 {
                color = GRASS_LIGHT;
            }
            if x + y > 21 {
                color = LEAF_DARK;
            }
            if draw::hash01(x, y, seed) < 0.15 {
                color = LEAF_DARK;
            }
            img.set(x as u32, y as u32, color);
        }
    }
}

/// A leaf blade: a short diagonal run with a lit upper edge.
///
/// Every leaf in this module is the same green — one tone is what keeps six
/// crops reading as one set of plants — so the two colours are not parameters.
fn leaf(img: &mut Image, x: i32, y: i32, dx: i32, dy: i32, len: i32) {
    for step in 0..len {
        let px = x + dx * step;
        let py = y + dy * step;
        draw::put(img, px, py, LEAF_MID);
        if dy >= 0 {
            draw::put(img, px, py - 1, GRASS_LIGHT);
        } else {
            draw::put(img, px + 1, py, GRASS_LIGHT);
        }
    }
}

/// Parsnip: a fan of feathery leaves over a root that shoulders out of the soil.
fn parsnip(stage: usize) -> Image {
    const HEIGHT: [i32; STAGES] = [2, 4, 6, 8, 10];
    const LEAVES: [i32; STAGES] = [2, 3, 4, 5, 6];
    if stage == 0 {
        return sprout(HEIGHT[0]);
    }
    let mut img = Image::transparent(TILE, TILE);
    let base = 15;
    let height = HEIGHT[stage];
    let leaves = LEAVES[stage];
    // The root: a cream shoulder, narrow where the leaves join and wide where
    // it disappears into the ground.
    if stage >= 3 {
        let half = if stage == 3 { 1 } else { 2 };
        for row in 0..3 {
            let width = half - row.max(0) / 2;
            rect(
                &mut img,
                8 - width,
                base - row,
                7 + width,
                base - row,
                PARSNIP_MID,
            );
        }
        draw::hline(&mut img, 8 - half, 7 + half, base, PARSNIP_DARK);
        draw::put(&mut img, 8 - half, base - 2, CAULI_LIGHT);
    }
    // The leaves fan out of the crown in pairs, two pixels apart.
    let top = if stage >= 3 { base - 3 } else { base };
    draw::vline(&mut img, 8, top - height, top, LEAF_DARK);
    for i in 0..leaves {
        let step = i;
        let (side, y) = if i % 2 == 0 {
            (-1, top - 2 - step)
        } else {
            (1, top - 1 - step)
        };
        let len = 2 + (step + 1) / 2;
        leaf(&mut img, 8, y, side, -1, len);
    }
    draw::put(&mut img, 8, top - height, GRASS_LIGHT);
    finish(&mut img);
    img
}

/// Cauliflower: a rosette of broad leaves with a pale curd in the middle.
fn cauliflower(stage: usize) -> Image {
    if stage == 0 {
        return sprout(2);
    }
    let mut img = Image::transparent(TILE, TILE);
    let clumps: &[(i32, i32, i32)] = match stage {
        1 => &[(8, 13, 2)],
        2 => &[(6, 13, 2), (10, 12, 2)],
        3 => &[(5, 12, 3), (11, 12, 3), (8, 14, 3)],
        _ => &[(4, 12, 3), (12, 12, 3), (6, 10, 3), (10, 10, 3), (8, 14, 3)],
    };
    foliage(&mut img, clumps, draw::seed_of("farm_cauliflower"));
    if stage >= 3 {
        // The curd: a bumpy white head sitting in the middle of the rosette,
        // which is the only part of a cauliflower anybody recognises.
        let r = if stage == 3 { 2 } else { 3 };
        let cy = if stage == 3 { 10 } else { 7 };
        disc(&mut img, 8, cy, r, CAULI_MID);
        for dy in -r..=r {
            for dx in -r..=r {
                if dx * dx + dy * dy > r * r {
                    continue;
                }
                let (x, y) = (8 + dx, cy + dy);
                if dx + dy < -1 {
                    draw::put(&mut img, x, y, CAULI_LIGHT);
                }
                if dx + dy > r {
                    draw::put(&mut img, x, y, CAULI_DARK);
                }
                if (dx + dy).rem_euclid(2) == 0 && dx + dy > -2 && dx + dy < r {
                    draw::put(&mut img, x, y, CAULI_LIGHT);
                }
            }
        }
        draw::put(&mut img, 8 - r, cy + r, LEAF_DARK);
        draw::put(&mut img, 8 + r, cy + r, LEAF_DARK);
    }
    finish(&mut img);
    img
}

/// Potato: a low leafy bush, and at the last stage the tubers heaved up out of
/// the ground around it.
fn potato(stage: usize) -> Image {
    if stage == 0 {
        return sprout(2);
    }
    let mut img = Image::transparent(TILE, TILE);
    let clumps: &[(i32, i32, i32)] = match stage {
        1 => &[(8, 13, 2)],
        2 => &[(6, 12, 2), (10, 12, 2), (8, 14, 2)],
        3 => &[(5, 11, 3), (11, 10, 3), (8, 8, 2)],
        _ => &[(4, 10, 3), (12, 10, 3), (8, 7, 3), (6, 13, 2), (10, 13, 2)],
    };
    foliage(&mut img, clumps, draw::seed_of("farm_potato"));
    if stage == 4 {
        // Tubers: the whole point of growing a potato, so they are drawn large
        // enough to read as potatoes rather than as stones, spaced out so they
        // do not merge into one brown mound, and each with an eye in it.
        for (x, y, rx, ry) in [(3, 13, 3, 1), (12, 12, 3, 1), (8, 15, 3, 1)] {
            oval(&mut img, x, y, rx, ry, POTATO_MID);
            draw::hline(&mut img, x - rx + 1, x + rx - 1, y + ry, POTATO_DARK);
            draw::put(&mut img, x - 1, y, POTATO_DARK);
            draw::put(&mut img, x + 2, y, POTATO_DARK);
            draw::put(&mut img, x, y - 1, SAND_LIGHT);
        }
    }
    finish(&mut img);
    img
}

/// Tomato: a bushy plant that carries three red fruit when it is ripe.
fn tomato(stage: usize) -> Image {
    if stage == 0 {
        return sprout(2);
    }
    let mut img = Image::transparent(TILE, TILE);
    // The cane the plant is trained up, behind the leaves: it grows with the
    // plant, because a bare stick over a seedling reads as a mistake.
    const CANE: [i32; STAGES] = [0, 5, 8, 10, 12];
    draw::vline(&mut img, 8, 15 - CANE[stage], 14, LEAF_DARK);
    let clumps: &[(i32, i32, i32)] = match stage {
        1 => &[(7, 12, 2), (9, 11, 2)],
        2 => &[(6, 11, 2), (10, 10, 2), (8, 8, 2)],
        3 => &[(5, 10, 3), (11, 9, 3), (8, 7, 3), (8, 13, 2)],
        _ => &[(4, 9, 3), (12, 9, 3), (8, 6, 3), (6, 13, 3), (11, 13, 3)],
    };
    foliage(&mut img, clumps, draw::seed_of("farm_tomato"));
    if stage >= 4 {
        // Three fruit hanging in front of the mass: the calyx and the lit
        // shoulder are what make a red disc read as a tomato.
        for (x, y, r) in [(4, 11, 2), (12, 11, 2), (8, 14, 2)] {
            disc(&mut img, x, y, r, TOMATO_MID);
            draw::put(&mut img, x - 1, y - 1, TOMATO_LIGHT);
            draw::put(&mut img, x + r - 1, y + r - 1, TOMATO_DARK);
            draw::put(&mut img, x + r - 2, y + r, TOMATO_DARK);
            draw::put(&mut img, x, y - r, LEAF_DARK);
            draw::put(&mut img, x - 1, y - r, LEAF_MID);
            draw::put(&mut img, x + 1, y - r, LEAF_MID);
        }
    } else if stage == 3 {
        draw::put(&mut img, 8, 12, TOMATO_DARK);
        draw::put(&mut img, 7, 12, LEAF_MID);
    }
    finish(&mut img);
    img
}

/// Maize: tall stalks with long blades and a cob in the leaf axil.
///
/// The one crop whose silhouette is vertical: from stage 2 the stalks reach the
/// top of the cell, which is what makes a maize field look different from every
/// other field at a glance.
fn corn(stage: usize) -> Image {
    const HEIGHT: [i32; STAGES] = [3, 6, 10, 13, 16];
    const STALKS: [usize; STAGES] = [1, 2, 3, 3, 4];
    if stage == 0 {
        return sprout(3);
    }
    let mut img = Image::transparent(TILE, TILE);
    let base = 15;
    let height = HEIGHT[stage];
    let xs = [4, 8, 12, 6, 10];
    for (i, x) in xs.iter().take(STALKS[stage]).enumerate() {
        let x = *x;
        // Clamped, so the tallest stalks are cut off by the cell's own edge
        // rather than losing their tips to a negative coordinate.
        let top = (base - height + (i as i32 % 2)).max(0);
        // Two pixels wide, so a maize stalk reads as a stalk and not as a wire.
        draw::vline(&mut img, x, top, base, LEAF_DARK);
        draw::vline(
            &mut img,
            x + 1,
            top + 1,
            base,
            if i % 2 == 0 { LEAF_MID } else { LEAF_DARK },
        );
        if i % 2 == 0 {
            draw::vline(&mut img, x, top, base, LEAF_MID);
            draw::put(&mut img, x + 1, base, LEAF_DARK);
        }
        // Blades arching off the stalk, alternating sides.
        for step in 0..3 {
            let y = top + 2 + step * (height / 4).max(2);
            if y >= base {
                break;
            }
            let side = if (i + step as usize) % 2 == 0 { -1 } else { 1 };
            leaf(&mut img, x, y, side, 0, 3);
            draw::put(&mut img, x + side * 3, y - 1, GRASS_LIGHT);
            draw::put(&mut img, x + side, y + 1, LEAF_DARK);
        }
        // The tassel, once the stalk is tall enough to have one.
        if stage >= 3 {
            draw::put(&mut img, x, top - 1, CORN_LIGHT);
            draw::put(&mut img, x - 1, top, CORN_MID);
            draw::put(&mut img, x + 1, top, CORN_MID);
            draw::put(&mut img, x + 2, top + 1, CORN_MID);
        }
    }
    if stage >= 4 {
        // One cob, husked, hanging in the leaves of the middle stalk.
        rect(&mut img, 6, 7, 9, 12, CORN_MID);
        draw::vline(&mut img, 6, 7, 12, CORN_LIGHT);
        draw::vline(&mut img, 9, 7, 12, CORN_DARK);
        for y in 7..=12 {
            if y % 2 == 1 {
                draw::put(&mut img, 7, y, CORN_LIGHT);
            }
        }
        draw::hline(&mut img, 6, 9, 13, CORN_DARK);
        leaf(&mut img, 5, 8, -1, 1, 3);
        leaf(&mut img, 10, 9, 1, 1, 3);
        leaf(&mut img, 5, 12, -1, 0, 2);
    }
    finish(&mut img);
    img
}

/// Pumpkin: a vine that runs along the ground and, at the last stage, a great
/// orange fruit sitting on it.
fn pumpkin(stage: usize) -> Image {
    const HEIGHT: [i32; STAGES] = [2, 3, 4, 5, 6];
    const VINE: [i32; STAGES] = [0, 3, 6, 9, 12];
    if stage == 0 {
        return sprout(HEIGHT[0]);
    }
    let mut img = Image::transparent(TILE, TILE);
    let base = 15;
    // The vine: a low runner going out to both sides from the crown.
    let run = VINE[stage];
    draw::hline(&mut img, 8 - run / 2, 8 + run / 2, base - 1, LEAF_DARK);
    draw::put(&mut img, 8, base - 2, LEAF_MID);
    // Broad leaves along the runner.
    for i in 0..(1 + stage as i32 / 2) {
        let side = if i % 2 == 0 { -1 } else { 1 };
        let x = 8 + side * (2 + i);
        let y = base - 2 - i / 2;
        oval(&mut img, x, y - 1, 2, 2, LEAF_MID);
        draw::put(&mut img, x - 1, y - 3, GRASS_LIGHT);
        draw::put(&mut img, x + 1, y, LEAF_DARK);
        draw::hline(&mut img, x - 1, x + 1, y, LEAF_DARK);
    }
    if stage >= 3 {
        // A green fruit, then the ripe one: the pumpkin grows into place rather
        // than appearing from nowhere, and at stage 3 it is drawn in front of
        // the leaves so the young fruit is actually visible.
        let r = if stage == 3 { 3 } else { 4 };
        let cy = base - r - 1;
        oval(&mut img, 8, cy, r, r - 1, PUMPKIN_MID);
        for rib in -r..=r {
            if rib.rem_euclid(2) == 0 {
                continue;
            }
            let dy = r - 1;
            for y in -dy..=dy {
                let x = 8 + rib;
                let within = (rib * rib * dy * dy + y * y * r * r) <= r * r * dy * dy;
                if within {
                    draw::put(&mut img, x, cy + y, PUMPKIN_DARK);
                    draw::put(&mut img, x + 1, cy + y, PUMPKIN_LIGHT);
                }
            }
        }
        if stage == 3 {
            draw::hline(&mut img, 7, 9, cy - 2, LEAF_DARK);
            draw::put(&mut img, 8, cy - 3, GRASS_DARK);
        }
        if stage == 4 {
            draw::put(&mut img, 4, cy - 2, PUMPKIN_LIGHT);
            draw::put(&mut img, 8, cy - r + 1, LEAF_DARK);
            draw::put(&mut img, 8, cy - r, GRASS_DARK);
            draw::put(&mut img, 9, cy - r, GRASS_DARK);
        }
    }
    finish(&mut img);
    img
}

// --- props -----------------------------------------------------------------

/// Every prop, in sheet order.
fn prop_sprites() -> Vec<(String, Image)> {
    PROPS
        .iter()
        .filter_map(|spec| prop(spec.name).map(|image| (spec.name.to_string(), image)))
        .collect()
}

/// One prop by name, drawn in its own cell.
#[must_use]
pub fn prop(name: &str) -> Option<Image> {
    let image = match name {
        "tree_oak" => tree_oak(),
        "tree_pine" => tree_pine(),
        "tree_stump" => tree_stump(),
        "bush" => bush(),
        "rock_small" => rock(11, 9, 2, 6),
        "rock_large" => rock(15, 13, 0, 2),
        "log" => log(),
        "fence_h" => fence_h(),
        "fence_v" => fence_v(),
        "gate" => gate(),
        "sign" => sign(),
        "shipping_bin" => shipping_bin(),
        "flower_red" => flower(ROOF_RED, ROOF_LIGHT),
        "flower_blue" => flower(BLUE_MID, BLUE_LIGHT),
        "flower_yellow" => flower(CORN_MID, CORN_LIGHT),
        "mushroom" => mushroom(),
        "crate" => crate_box(),
        "sprinkler" => sprinkler(),
        "scarecrow" => scarecrow(),
        "well" => well(),
        "farmhouse" => farmhouse(),
        "shop" => shop(),
        "barn" => barn(),
        "greenhouse" => greenhouse(),
        _ => return None,
    };
    Some(image)
}

/// An oak: a heavy bole under a canopy of overlapping clumps.
///
/// The canopy is built from six discs so its silhouette is bumpy rather than
/// round, and the light is applied in two passes — a broad top-left highlight
/// and a bottom-right shadow — before a hash breaks the boundary between them
/// up into leaf texture.
fn tree_oak() -> Image {
    let mut img = Image::transparent(32, 48);
    let seed = draw::seed_of("farm_oak");
    // The bole, drawn first so the canopy can hang over it.
    rect(&mut img, 14, 28, 17, 45, DIRT_MID);
    draw::vline(&mut img, 14, 28, 45, DIRT_LIGHT);
    draw::vline(&mut img, 17, 28, 45, DIRT_DARK);
    draw::vline(&mut img, 16, 30, 45, DIRT_DARK);
    // Roots flaring into the ground.
    rect(&mut img, 12, 42, 19, 46, DIRT_MID);
    draw::hline(&mut img, 11, 20, 47, DIRT_DARK);
    draw::put(&mut img, 11, 45, DIRT_DARK);
    draw::put(&mut img, 20, 45, DIRT_DARK);
    draw::put(&mut img, 12, 42, DIRT_LIGHT);
    // The canopy.
    let clumps = [
        (10, 14, 8),
        (21, 14, 8),
        (16, 8, 9),
        (7, 21, 6),
        (24, 21, 6),
        (16, 18, 9),
        (16, 26, 7),
    ];
    for (cx, cy, r) in clumps {
        disc(&mut img, cx, cy, r, LEAF_MID);
    }
    for y in 0..36 {
        for x in 0..32 {
            if img.get(x, y) != Some(LEAF_MID) {
                continue;
            }
            let xi = x as i32;
            let yi = y as i32;
            let lit = (xi - 9) + (yi - 6);
            let mut color = LEAF_MID;
            if lit < 4 {
                color = GRASS_LIGHT;
            }
            if xi + yi > 40 {
                color = LEAF_DARK;
            }
            if draw::hash01(xi, yi, seed) < 0.18 {
                color = LEAF_DARK;
            }
            if draw::hash01(xi, yi, seed ^ 0x44) < 0.10 && color == LEAF_MID {
                color = GRASS_LIGHT;
            }
            img.set(x, y, color);
        }
    }
    finish(&mut img);
    img
}

/// A pine: five tiers of dark needles on a short trunk.
///
/// Every tier is a triangle with a flat, skirted bottom edge, and each one
/// overhangs the one below it. That stepped profile is the whole difference
/// between a conifer and a broadleaf at sixteen pixels wide.
fn tree_pine() -> Image {
    let mut img = Image::transparent(32, 48);
    // Trunk: short, and mostly hidden behind the lowest skirt.
    rect(&mut img, 14, 34, 17, 47, DIRT_DARK);
    draw::vline(&mut img, 14, 34, 47, DIRT_MID);
    draw::hline(&mut img, 12, 19, 47, DIRT_DARK);
    draw::put(&mut img, 12, 46, DIRT_MID);
    draw::put(&mut img, 19, 46, DIRT_MID);
    // Tiers, top first, each starting four rows above the skirt of the one
    // before it: `(apex row, height, half width at the skirt)`. Overlapping
    // them is what makes a stack of triangles read as one conifer.
    let tiers = [
        (1, 11, 4),
        (7, 11, 7),
        (13, 12, 10),
        (19, 13, 13),
        (25, 14, 15),
    ];
    for (apex, height, half) in tiers {
        for row in 0..height {
            let y = apex + row;
            let w = 1 + row * half / (height - 1);
            for x in (16 - w)..=(15 + w) {
                // Light from the top-left: the left half of every tier is lit,
                // the right half falls away.
                let color = if x < 16 - w / 2 { LEAF_MID } else { LEAF_DARK };
                img.set(x as u32, y as u32, color);
            }
        }
        // The skirt, and a lit needle on its left shoulder.
        let skirt = apex + height - 1;
        draw::hline(&mut img, 16 - half, 15 + half, skirt, LEAF_DARK);
        draw::put(&mut img, 16 - half + 1, skirt - 1, GRASS_LIGHT);
        draw::put(&mut img, 16 - half + 2, skirt - 2, LEAF_MID);
    }
    // The leader at the very top catches the sun.
    draw::vline(&mut img, 16, 1, 7, GRASS_LIGHT);
    draw::put(&mut img, 15, 4, GRASS_LIGHT);
    draw::put(&mut img, 15, 9, GRASS_LIGHT);
    draw::put(&mut img, 14, 15, GRASS_LIGHT);
    finish(&mut img);
    img
}

/// A stump: a bark cylinder under a cut face with growth rings in it.
///
/// The cut face is the whole read — a stump is a cylinder seen from slightly
/// above — so the ellipse is wide, the rings inside it are two tones, and the
/// bark below it is broken up with dark fissures.
fn tree_stump() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    // The bark cylinder, narrower than the cut face so the top overhangs it:
    // that overhang is what stops the sprite reading as a box.
    rect(&mut img, 4, 6, 11, 13, DIRT_MID);
    draw::vline(&mut img, 4, 6, 13, DIRT_LIGHT);
    draw::vline(&mut img, 11, 6, 13, DIRT_DARK);
    for y in 8..13 {
        draw::put(&mut img, 6, y, DIRT_DARK);
        draw::put(&mut img, 9, y, DIRT_DARK);
        draw::put(&mut img, 7, y + 1, DIRT_DARK);
    }
    // The cut face: a wide ellipse with a growth ring in it, lit top-left.
    oval(&mut img, 8, 5, 6, 3, DIRT_LIGHT);
    for dy in -3..=3 {
        for dx in -6..=6 {
            let d2 = dx * dx * 9 + dy * dy * 36;
            if (135..=324).contains(&d2) {
                draw::put(&mut img, 8 + dx, 5 + dy, DIRT_MID);
            }
        }
    }
    draw::put(&mut img, 7, 5, DIRT_MID);
    draw::put(&mut img, 9, 5, DIRT_MID);
    draw::hline(&mut img, 4, 7, 3, SAND_LIGHT);
    // Roots flaring into the ground.
    draw::hline(&mut img, 3, 6, 13, DIRT_DARK);
    draw::hline(&mut img, 9, 12, 13, DIRT_DARK);
    draw::put(&mut img, 3, 12, DIRT_MID);
    draw::put(&mut img, 12, 12, DIRT_MID);
    finish(&mut img);
    img
}

/// A leafy bush, with berries in it so it is not just a green blob.
fn bush() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    let seed = draw::seed_of("farm_bush");
    for (cx, cy, r) in [(5, 10, 4), (10, 10, 4), (7, 7, 4)] {
        disc(&mut img, cx, cy, r, LEAF_MID);
    }
    for y in 0..TILE as i32 {
        for x in 0..TILE as i32 {
            if img.get(x as u32, y as u32) != Some(LEAF_MID) {
                continue;
            }
            let mut color = LEAF_MID;
            if (x - 4) + (y - 5) < 2 {
                color = GRASS_LIGHT;
            }
            if draw::hash01(x, y, seed) < 0.22 || x + y > 20 {
                color = LEAF_DARK;
            }
            img.set(x as u32, y as u32, color);
        }
    }
    for (x, y) in [(5, 9), (10, 12), (8, 6)] {
        draw::put(&mut img, x, y, TOMATO_MID);
        draw::put(&mut img, x, y - 1, TOMATO_LIGHT);
    }
    finish(&mut img);
    img
}

/// A boulder of `w` by `h` pixels, bottom-left at `(ox, oy)`.
fn rock(w: i32, h: i32, ox: i32, oy: i32) -> Image {
    let mut img = Image::transparent(TILE, TILE);
    let seed = draw::seed_of("farm_rock");
    let (rx, ry) = (w / 2, h / 2);
    oval(&mut img, ox + rx, oy + ry, rx, ry, STONE_MID);
    for dy in 0..h {
        for dx in 0..w {
            let x = ox + dx;
            let y = oy + dy;
            if img.get(x as u32, y as u32) != Some(STONE_MID) {
                continue;
            }
            let mut color = STONE_MID;
            if dy * 3 < h {
                color = STONE_LIGHT;
            }
            if dy * 3 > h * 2 {
                color = STONE_DARK;
            }
            if draw::hash01(x, y, seed) < 0.16 {
                color = if color == STONE_LIGHT {
                    STONE_MID
                } else {
                    STONE_LIGHT
                };
            }
            img.set(x as u32, y as u32, color);
        }
    }
    // Two facets, which is what stops a small rock reading as a pebble and a
    // large one as a pillow: a lit plane across the upper left and a chip out
    // of the lower right, plus a crack between them.
    draw::hline(&mut img, ox + 1, ox + w / 3, oy + h / 3, STONE_LIGHT);
    draw::hline(&mut img, ox + w / 2, ox + w - 2, oy + h - h / 3, STONE_DARK);
    for step in 0..h / 2 {
        draw::put(&mut img, ox + w / 3 + step, oy + h / 3 + step, STONE_DARK);
        draw::put(
            &mut img,
            ox + w / 3 + step,
            oy + h / 3 + step + 1,
            STONE_LIGHT,
        );
    }
    draw::put(&mut img, ox + 1, oy + h - 2, STONE_DARK);
    finish(&mut img);
    img
}

/// A fallen log: bark along the top, end grain at the right.
fn log() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    // The trunk, lying along the cell: lit along its top, dark underneath.
    rect(&mut img, 0, 6, 12, 12, DIRT_MID);
    draw::hline(&mut img, 0, 12, 5, DIRT_LIGHT);
    draw::hline(&mut img, 0, 12, 6, DIRT_LIGHT);
    draw::hline(&mut img, 0, 12, 12, DIRT_DARK);
    draw::hline(&mut img, 0, 12, 11, DIRT_DARK);
    // Bark: fissures wandering along the length.
    for x in 1..12 {
        let y = 7 + (draw::hash01(x, 1, 0x109) * 3.0) as i32;
        draw::put(&mut img, x, y, DIRT_DARK);
        draw::put(&mut img, x, y + 1, DIRT_LIGHT);
    }
    // The sawn end, with a ring in it.
    oval(&mut img, 12, 9, 2, 4, DIRT_LIGHT);
    oval(&mut img, 12, 9, 1, 2, DIRT_MID);
    draw::put(&mut img, 12, 9, DIRT_DARK);
    draw::put(&mut img, 13, 6, DIRT_DARK);
    draw::put(&mut img, 13, 12, DIRT_DARK);
    finish(&mut img);
    img
}

/// A fence running left to right: two posts, two rails.
///
/// The rails run off both edges of the cell, so a row of these reads as one
/// fence rather than as a row of panels.
fn fence_h() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    for y in [6, 10] {
        plank(&mut img, 0, 15, y + 1, DIRT_MID, DIRT_LIGHT, DIRT_DARK);
    }
    for x in [3, 11] {
        rect(&mut img, x, 3, x + 1, 14, DIRT_MID);
        draw::vline(&mut img, x, 3, 14, DIRT_LIGHT);
        draw::vline(&mut img, x + 1, 3, 14, DIRT_DARK);
        draw::hline(&mut img, x, x + 1, 3, DIRT_LIGHT);
    }
    finish(&mut img);
    img
}

/// The same fence turned: the rails run off the top and bottom of the cell.
fn fence_v() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    for x in [6, 10] {
        draw::vline(&mut img, x, 0, 15, DIRT_LIGHT);
        draw::vline(&mut img, x + 1, 0, 15, DIRT_MID);
        draw::vline(&mut img, x + 2, 0, 15, DIRT_DARK);
    }
    for y in [3, 11] {
        rect(&mut img, 3, y, 14, y + 1, DIRT_MID);
        draw::hline(&mut img, 3, 14, y, DIRT_LIGHT);
        draw::hline(&mut img, 3, 14, y + 1, DIRT_DARK);
    }
    finish(&mut img);
    img
}

/// A gate: a braced frame between two posts, with a latch.
fn gate() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    // Hanging posts.
    for x in [0, 13] {
        rect(&mut img, x, 1, x + 2, 14, DIRT_MID);
        draw::vline(&mut img, x, 1, 14, DIRT_LIGHT);
        draw::vline(&mut img, x + 2, 1, 14, DIRT_DARK);
    }
    // The frame: top rail, bottom rail, and a diagonal brace between them.
    plank(&mut img, 3, 12, 4, DIRT_MID, DIRT_LIGHT, DIRT_DARK);
    plank(&mut img, 3, 12, 12, DIRT_MID, DIRT_LIGHT, DIRT_DARK);
    for step in 0..6 {
        draw::put(&mut img, 4 + step, 11 - step, DIRT_LIGHT);
        draw::put(&mut img, 4 + step, 12 - step, DIRT_DARK);
    }
    for y in [7, 8] {
        draw::hline(&mut img, 3, 12, y, DIRT_MID);
    }
    // The latch.
    draw::put(&mut img, 11, 8, STONE_LIGHT);
    draw::put(&mut img, 12, 8, STONE_MID);
    finish(&mut img);
    img
}

/// A signpost: a board with two lines of writing on a post.
fn sign() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    // The post.
    rect(&mut img, 6, 8, 8, 15, DIRT_MID);
    draw::vline(&mut img, 6, 8, 15, DIRT_LIGHT);
    draw::vline(&mut img, 8, 8, 15, DIRT_DARK);
    // The board, tipped slightly so it catches the light on its top edge.
    rect(&mut img, 1, 1, 14, 8, DIRT_LIGHT);
    draw::hline(&mut img, 1, 14, 1, SAND_LIGHT);
    draw::hline(&mut img, 1, 14, 8, DIRT_DARK);
    draw::vline(&mut img, 1, 1, 8, DIRT_MID);
    draw::vline(&mut img, 14, 1, 8, DIRT_DARK);
    // Writing, as two ruled lines of dashes.
    for x in [3, 5, 7, 9, 11] {
        draw::put(&mut img, x, 3, SHADOW);
        draw::put(&mut img, x, 5, SHADOW);
    }
    draw::put(&mut img, 11, 5, DIRT_LIGHT);
    finish(&mut img);
    img
}

/// A shipping bin: a slatted box with its lid propped open behind it.
///
/// The open lid is the whole read — a closed box is a crate, and this one has
/// to say "put things in me" from across the farm.
fn shipping_bin() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    // The lid, leaning back and to the left, with a batten across it.
    for row in 0..4 {
        let x0 = 3 - row / 2;
        draw::hline(&mut img, x0, x0 + 11, 1 + row, DIRT_LIGHT);
        draw::hline(
            &mut img,
            x0,
            x0 + 11,
            1 + row,
            if row == 0 { SAND_LIGHT } else { DIRT_MID },
        );
    }
    draw::hline(&mut img, 2, 13, 4, DIRT_DARK);
    // The open mouth: dark, with something in it.
    rect(&mut img, 2, 5, 13, 7, SHADOW);
    draw::put(&mut img, 5, 6, PUMPKIN_MID);
    draw::put(&mut img, 6, 6, TOMATO_MID);
    draw::put(&mut img, 9, 6, CORN_MID);
    draw::hline(&mut img, 2, 13, 5, DIRT_DARK);
    // The box: vertical slats with a lit rim.
    rect(&mut img, 1, 8, 14, 15, DIRT_MID);
    for x in (3..14).step_by(3) {
        draw::vline(&mut img, x, 8, 15, DIRT_DARK);
        draw::vline(&mut img, x + 1, 8, 15, DIRT_LIGHT);
    }
    draw::hline(&mut img, 1, 14, 8, DIRT_LIGHT);
    draw::hline(&mut img, 1, 14, 15, DIRT_DARK);
    draw::hline(&mut img, 1, 14, 11, DIRT_DARK);
    draw::vline(&mut img, 1, 8, 15, DIRT_LIGHT);
    draw::vline(&mut img, 14, 8, 15, DIRT_DARK);
    finish(&mut img);
    img
}

/// A roadside flower: a stem, two leaves, five petals.
fn flower(petal: Color8, light: Color8) -> Image {
    let mut img = Image::transparent(TILE, TILE);
    draw::vline(&mut img, 7, 8, 14, GRASS_MID);
    draw::put(&mut img, 6, 11, GRASS_LIGHT);
    draw::put(&mut img, 5, 10, GRASS_MID);
    draw::put(&mut img, 8, 12, GRASS_DARK);
    draw::put(&mut img, 9, 13, GRASS_MID);
    draw::put(&mut img, 7, 4, petal);
    draw::put(&mut img, 6, 5, petal);
    draw::put(&mut img, 8, 5, light);
    draw::put(&mut img, 7, 6, petal);
    draw::put(&mut img, 9, 4, light);
    draw::put(&mut img, 5, 4, light);
    draw::put(&mut img, 7, 5, SAND_LIGHT);
    finish(&mut img);
    img
}

/// A mushroom: a spotted red cap over a pale stem.
fn mushroom() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    // Stem, with a ring.
    rect(&mut img, 6, 9, 9, 14, PLASTER_MID);
    draw::vline(&mut img, 6, 9, 14, PLASTER_DARK);
    draw::vline(&mut img, 9, 9, 14, PLASTER_DARK);
    draw::hline(&mut img, 5, 10, 10, PLASTER_DARK);
    // Cap.
    oval(&mut img, 8, 6, 7, 4, ROOF_RED);
    draw::hline(&mut img, 1, 15, 8, ROOF_RED);
    draw::hline(&mut img, 1, 15, 9, ROOF_DARK);
    draw::hline(&mut img, 3, 8, 3, ROOF_LIGHT);
    draw::put(&mut img, 2, 5, ROOF_DARK);
    for (x, y) in [(4, 5), (9, 4), (12, 6), (6, 7)] {
        draw::put(&mut img, x, y, FOAM);
        draw::put(&mut img, x + 1, y, PLASTER_MID);
    }
    finish(&mut img);
    img
}

/// A slatted crate with a lid and corner brackets.
fn crate_box() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    rect(&mut img, 2, 3, 13, 14, DIRT_MID);
    draw::frame(&mut img, Area::new(2, 3, 13, 14), DIRT_DARK);
    draw::hline(&mut img, 2, 13, 3, DIRT_LIGHT);
    draw::vline(&mut img, 2, 3, 14, DIRT_LIGHT);
    // Boards across the front.
    for y in [6, 9, 12] {
        draw::hline(&mut img, 3, 12, y, DIRT_DARK);
        draw::hline(&mut img, 3, 12, y - 1, DIRT_LIGHT);
    }
    // Corner brackets.
    for (x, y) in [(3, 4), (12, 4), (3, 13), (12, 13)] {
        draw::put(&mut img, x, y, STONE_MID);
    }
    finish(&mut img);
    img
}

/// A sprinkler: a brass head on a stake, throwing four jets.
fn sprinkler() -> Image {
    let mut img = Image::transparent(TILE, TILE);
    // Stake.
    rect(&mut img, 7, 9, 8, 15, STONE_DARK);
    draw::vline(&mut img, 7, 9, 15, STONE_MID);
    // Head.
    rect(&mut img, 5, 6, 10, 9, STONE_MID);
    draw::hline(&mut img, 5, 10, 6, STONE_LIGHT);
    draw::hline(&mut img, 5, 10, 9, STONE_DARK);
    draw::put(&mut img, 8, 7, GOLD_MID);
    // Jets.
    for (x, y) in [(2, 4), (13, 4), (4, 2), (11, 2)] {
        draw::put(&mut img, x, y, WATER_SHALLOW);
        draw::put(&mut img, x + 1, y + 1, WATER_MID);
    }
    draw::put(&mut img, 8, 4, FOAM);
    draw::put(&mut img, 8, 3, WATER_SHALLOW);
    finish(&mut img);
    img
}

/// A scarecrow: a post, a crossbar, a sack head and a straw-stuffed coat.
fn scarecrow() -> Image {
    let mut img = Image::transparent(TILE, 32);
    // Post and crossbar.
    rect(&mut img, 7, 12, 8, 31, DIRT_DARK);
    draw::vline(&mut img, 7, 12, 31, DIRT_MID);
    rect(&mut img, 1, 11, 14, 12, DIRT_DARK);
    draw::hline(&mut img, 1, 14, 11, DIRT_MID);
    // Straw at the ends of the arms.
    for x in [1, 2, 13, 14] {
        draw::put(&mut img, x, 10, STRAW_MID);
        draw::put(&mut img, x, 13, STRAW_DARK);
    }
    // The coat: a sack body, wider at the hem.
    for y in 13..26 {
        let t = y - 13;
        let half = 3 + t / 3;
        rect(&mut img, 8 - half, y, 7 + half, y, STRAW_MID);
        draw::put(&mut img, 8 - half, y, STRAW_DARK);
        draw::put(&mut img, 8 - half + 1, y, UI_PALE_MID);
        draw::put(&mut img, 7 + half, y, STRAW_DARK);
    }
    for x in 1..15i32 {
        if (x + 13).rem_euclid(3) == 0 {
            draw::put(&mut img, x, 25, STRAW_DARK);
            draw::put(&mut img, x, 26, STRAW_MID);
        }
    }
    // The head: a sack, with a stitched face.
    rect(&mut img, 5, 4, 10, 12, UI_PALE_MID);
    draw::vline(&mut img, 5, 4, 12, UI_PALE_LIGHT);
    draw::vline(&mut img, 10, 4, 12, UI_PALE_DARK);
    draw::put(&mut img, 6, 8, SHADOW);
    draw::put(&mut img, 9, 8, SHADOW);
    draw::hline(&mut img, 7, 8, 10, SHADOW);
    draw::put(&mut img, 7, 6, STRAW_DARK);
    draw::put(&mut img, 8, 6, STRAW_DARK);
    // The hat: a cone, so the head silhouette is unmistakable.
    rect(&mut img, 4, 3, 11, 4, STRAW_MID);
    draw::hline(&mut img, 4, 11, 4, STRAW_DARK);
    rect(&mut img, 6, 1, 9, 2, STRAW_MID);
    draw::hline(&mut img, 6, 9, 2, STRAW_DARK);
    draw::put(&mut img, 7, 0, STRAW_MID);
    draw::put(&mut img, 8, 0, STRAW_MID);
    finish(&mut img);
    img
}

/// A stone well: a ring, two posts, a shingled gable and a bucket on a rope.
fn well() -> Image {
    let mut img = Image::transparent(32, 32);
    // The shingled roof.
    for y in 0..9 {
        let half = 4 + y * 2;
        let (x0, x1) = (15 - half, 16 + half);
        let color = if y < 2 { ROOF_LIGHT } else { ROOF_RED };
        rect(&mut img, x0.max(1), y + 3, x1.min(30), y + 3, color);
        draw::put(&mut img, x0.max(1), y + 3, ROOF_DARK);
        draw::put(&mut img, x1.min(30), y + 3, ROOF_DARK);
        if y % 3 == 2 {
            draw::hline(&mut img, x0.max(1), x1.min(30), y + 3, ROOF_DARK);
        }
    }
    draw::hline(&mut img, 1, 30, 12, ROOF_DARK);
    draw::hline(&mut img, 2, 29, 2, ROOF_LIGHT);
    // Posts.
    rect(&mut img, 5, 12, 6, 20, DIRT_MID);
    rect(&mut img, 25, 12, 26, 20, DIRT_DARK);
    // The stone ring.
    rect(&mut img, 3, 19, 28, 28, STONE_MID);
    draw::hline(&mut img, 3, 28, 19, STONE_LIGHT);
    draw::hline(&mut img, 3, 28, 28, STONE_DARK);
    draw::vline(&mut img, 3, 19, 28, STONE_LIGHT);
    draw::vline(&mut img, 28, 19, 28, STONE_DARK);
    for step in 0..6 {
        draw::put(&mut img, 4 + step * 4, 23, STONE_DARK);
        draw::put(&mut img, 6 + step * 4, 26, STONE_DARK);
    }
    // The shaft, and water down it.
    rect(&mut img, 7, 19, 24, 24, SHADOW);
    rect(&mut img, 8, 22, 23, 24, WATER_DEEP);
    draw::hline(&mut img, 8, 23, 22, WATER_SHALLOW);
    draw::put(&mut img, 11, 23, FOAM);
    // Bucket and rope.
    draw::vline(&mut img, 15, 13, 15, DIRT_DARK);
    rect(&mut img, 13, 16, 18, 19, DIRT_MID);
    draw::hline(&mut img, 13, 18, 16, DIRT_LIGHT);
    draw::hline(&mut img, 13, 18, 19, DIRT_DARK);
    finish(&mut img);
    img
}

/// The farmhouse: gable roof, chimney, door, two windows.
fn farmhouse() -> Image {
    let mut img = Image::transparent(64, 64);
    let seed = draw::seed_of("farmhouse");
    // Walls.
    rect(&mut img, 6, 30, 57, 58, PLASTER_MID);
    draw::dither(&mut img, Area::new(6, 40, 57, 58), PLASTER_DARK, seed);
    // The foundation, in stone.
    rect(&mut img, 5, 55, 58, 59, STONE_MID);
    draw::hline(&mut img, 5, 58, 55, STONE_LIGHT);
    draw::hline(&mut img, 5, 58, 59, STONE_DARK);
    for x in (7..57).step_by(7) {
        draw::vline(&mut img, x, 55, 59, STONE_DARK);
    }
    // Corner boards.
    for x in [6, 56] {
        rect(&mut img, x, 30, x + 1, 58, DIRT_MID);
        draw::vline(&mut img, x, 30, 58, DIRT_LIGHT);
        draw::vline(&mut img, x + 1, 30, 58, DIRT_DARK);
    }
    // Roof: a gable with the ridge at the top, shingled in course.
    for y in 4..32 {
        let half = 2 + (y - 4) * 29 / 28;
        let (x0, x1) = (31 - half, 32 + half);
        for x in x0..=x1 {
            let color = if x <= 31 { ROOF_RED } else { ROOF_DARK };
            img.set(x as u32, y as u32, color);
        }
        if y % 4 == 3 {
            rect(&mut img, x0, y, x1, y, ROOF_DARK);
        }
        draw::put(&mut img, x0, y, ROOF_DARK);
    }
    draw::hline(&mut img, 29, 34, 4, ROOF_LIGHT);
    draw::vline(&mut img, 30, 5, 30, ROOF_LIGHT);
    // The eave board, which is also the shadow line the walls hang under.
    draw::hline(&mut img, 2, 61, 32, DIRT_LIGHT);
    draw::hline(&mut img, 2, 61, 33, DIRT_DARK);
    rect(&mut img, 1, 30, 3, 33, DIRT_MID);
    rect(&mut img, 60, 30, 62, 33, DIRT_MID);
    // Chimney.
    rect(&mut img, 45, 6, 52, 22, STONE_MID);
    draw::vline(&mut img, 45, 6, 22, STONE_LIGHT);
    draw::vline(&mut img, 52, 6, 22, STONE_DARK);
    for y in (8..22).step_by(4) {
        draw::hline(&mut img, 45, 52, y, STONE_DARK);
    }
    rect(&mut img, 44, 4, 53, 6, STONE_DARK);
    draw::hline(&mut img, 44, 53, 4, STONE_LIGHT);
    // The door, with a step and a lamp.
    rect(&mut img, 27, 40, 36, 58, DIRT_DARK);
    rect(&mut img, 28, 41, 35, 58, DIRT_MID);
    draw::vline(&mut img, 28, 41, 58, DIRT_LIGHT);
    draw::vline(&mut img, 35, 41, 58, DIRT_DARK);
    draw::hline(&mut img, 28, 35, 48, DIRT_DARK);
    draw::hline(&mut img, 28, 35, 47, DIRT_LIGHT);
    draw::put(&mut img, 33, 50, GOLD_MID);
    draw::hline(&mut img, 26, 37, 59, STONE_LIGHT);
    // Windows: frame, glass, mullions, sill.
    for x0 in [11, 43] {
        let (x1, y0, y1) = (x0 + 10, 36, 47);
        rect(&mut img, x0, y0, x1, y1, DIRT_DARK);
        rect(&mut img, x0 + 1, y0 + 1, x1 - 1, y1 - 1, WATER_SHALLOW);
        draw::hline(&mut img, x0 + 2, x1 - 2, y0 + 2, FOAM);
        draw::vline(&mut img, x0 + 5, y0 + 1, y1 - 1, DIRT_DARK);
        draw::hline(&mut img, x0 + 1, x1 - 1, y0 + 5, DIRT_DARK);
        draw::hline(&mut img, x0 + 1, x1 - 1, y1 - 1, WATER_MID);
        rect(&mut img, x0 - 1, y1 + 1, x1 + 1, y1 + 1, STONE_LIGHT);
    }
    finish(&mut img);
    img
}

/// The shop: a storefront with a striped awning, a sign and a shop window.
fn shop() -> Image {
    let mut img = Image::transparent(64, 48);
    // Walls.
    rect(&mut img, 4, 14, 59, 43, PLASTER_MID);
    draw::hline(&mut img, 4, 59, 14, FOAM);
    // Stone base.
    rect(&mut img, 3, 39, 60, 44, STONE_MID);
    draw::hline(&mut img, 3, 60, 39, STONE_LIGHT);
    draw::hline(&mut img, 3, 60, 44, STONE_DARK);
    for x in (6..60).step_by(8) {
        draw::vline(&mut img, x, 40, 44, STONE_DARK);
    }
    // The sign board, above the awning.
    rect(&mut img, 17, 2, 46, 10, DIRT_LIGHT);
    draw::frame(&mut img, Area::new(17, 2, 46, 10), DIRT_DARK);
    draw::hline(&mut img, 17, 46, 2, SAND_LIGHT);
    for x in (21..44).step_by(4) {
        rect(&mut img, x, 5, x + 2, 6, SHADOW);
    }
    // The awning: stripes, then a scalloped hem.
    for x in 2..62 {
        let stripe = (x / 5) % 2 == 0;
        let color = if stripe { ROOF_RED } else { PLASTER_MID };
        draw::vline(&mut img, x, 11, 18, color);
        if stripe {
            draw::put(&mut img, x, 11, ROOF_LIGHT);
        } else {
            draw::put(&mut img, x, 11, FOAM);
        }
    }
    for x in 2..62 {
        let notch = (x - 2) % 5;
        if notch < 3 {
            draw::put(
                &mut img,
                x,
                19,
                if (x / 5) % 2 == 0 {
                    ROOF_DARK
                } else {
                    PLASTER_DARK
                },
            );
        }
    }
    draw::hline(&mut img, 2, 61, 20, SHADOW);
    // The shop window and its counter.
    rect(&mut img, 8, 24, 24, 36, DIRT_DARK);
    rect(&mut img, 9, 25, 23, 35, WATER_SHALLOW);
    draw::hline(&mut img, 10, 22, 26, FOAM);
    draw::vline(&mut img, 16, 25, 35, DIRT_DARK);
    draw::hline(&mut img, 9, 23, 35, WATER_MID);
    rect(&mut img, 6, 36, 26, 38, DIRT_LIGHT);
    draw::hline(&mut img, 6, 26, 38, DIRT_DARK);
    // The door.
    rect(&mut img, 34, 24, 45, 43, DIRT_DARK);
    rect(&mut img, 35, 25, 44, 43, DIRT_MID);
    rect(&mut img, 36, 26, 43, 32, WATER_SHALLOW);
    draw::hline(&mut img, 36, 43, 26, FOAM);
    draw::vline(&mut img, 35, 25, 43, DIRT_LIGHT);
    draw::vline(&mut img, 44, 25, 43, DIRT_DARK);
    draw::put(&mut img, 42, 37, GOLD_MID);
    draw::hline(&mut img, 33, 46, 43, STONE_LIGHT);
    // Crates stacked against the wall.
    for (x, y) in [(49, 33), (49, 26)] {
        rect(&mut img, x, y, x + 9, y + 7, DIRT_MID);
        draw::frame(&mut img, Area::new(x, y, x + 9, y + 7), DIRT_DARK);
        draw::hline(&mut img, x, x + 9, y, DIRT_LIGHT);
        draw::hline(&mut img, x, x + 9, y + 4, DIRT_DARK);
    }
    finish(&mut img);
    img
}

/// The barn: a gambrel roof, red board walls and two big braced doors.
fn barn() -> Image {
    let mut img = Image::transparent(64, 64);
    // The gambrel roof: a steep upper slope breaking into a shallow lower one.
    for y in 2..26 {
        let half = if y < 14 {
            6 + (y - 2) * 24 / 12
        } else {
            30 + (y - 14) / 3
        };
        let (x0, x1) = (31 - half, 32 + half);
        for x in x0.max(1)..=x1.min(62) {
            img.set(x as u32, y as u32, ROOF_DARK);
        }
        if y % 3 == 0 {
            rect(&mut img, x0.max(1), y, x1.min(62), y, SHADOW);
        }
        draw::put(&mut img, x0.max(1), y, SHADOW);
    }
    draw::hline(&mut img, 29, 34, 2, ROOF_LIGHT);
    draw::vline(&mut img, 30, 3, 24, ROOF_LIGHT);
    // The walls: red boards under white trim.
    rect(&mut img, 4, 24, 59, 60, ROOF_RED);
    for x in (6..59).step_by(4) {
        draw::vline(&mut img, x, 24, 60, ROOF_DARK);
        draw::vline(&mut img, x + 1, 24, 60, ROOF_LIGHT);
    }
    draw::hline(&mut img, 4, 59, 24, PLASTER_MID);
    draw::hline(&mut img, 4, 59, 25, PLASTER_DARK);
    draw::hline(&mut img, 4, 59, 60, ROOF_DARK);
    for x in [4, 58] {
        rect(&mut img, x, 24, x + 1, 60, PLASTER_MID);
        draw::vline(&mut img, x + 1, 24, 60, PLASTER_DARK);
    }
    // The hayloft door, up in the gable.
    rect(&mut img, 27, 10, 36, 24, SHADOW);
    draw::frame(&mut img, Area::new(27, 10, 36, 24), PLASTER_MID);
    draw::hline(&mut img, 29, 34, 12, ROOF_DARK);
    draw::put(&mut img, 31, 4, STONE_LIGHT);
    draw::put(&mut img, 32, 4, STONE_LIGHT);
    // The big doors: two leaves, each with a white X brace.
    rect(&mut img, 19, 30, 44, 61, PLASTER_MID);
    for (x0, x1) in [(21, 31), (33, 43)] {
        rect(&mut img, x0, 32, x1, 60, ROOF_RED);
        draw::frame(&mut img, Area::new(x0, 32, x1, 60), ROOF_DARK);
        for step in 0..9 {
            draw::put(&mut img, x0 + 1 + step, 33 + step * 3, PLASTER_MID);
            draw::put(&mut img, x0 + 2 + step, 33 + step * 3, PLASTER_DARK);
            draw::put(&mut img, x1 - 1 - step, 33 + step * 3, PLASTER_MID);
            draw::put(&mut img, x1 - 2 - step, 33 + step * 3, PLASTER_DARK);
        }
        draw::vline(&mut img, x0 + (x1 - x0) / 2, 45, 60, PLASTER_MID);
    }
    draw::vline(&mut img, 32, 30, 61, SHADOW);
    draw::hline(&mut img, 19, 44, 61, STONE_DARK);
    finish(&mut img);
    img
}

/// The greenhouse: a glass gable over glass walls, with the beds showing
/// through.
fn greenhouse() -> Image {
    let mut img = Image::transparent(48, 48);
    // The glass roof: two slopes meeting at a ridge.
    for y in 4..21 {
        let half = 3 + (y - 4) * 20 / 16;
        let (x0, x1) = (23 - half, 24 + half);
        for x in x0.max(2)..=x1.min(45) {
            let lit = x <= 23;
            img.set(x as u32, y as u32, if lit { FOAM } else { WATER_SHALLOW });
            if !lit {
                img.set(x as u32, y as u32, WATER_MID);
            }
        }
        if (y - 4) % 4 == 0 {
            rect(&mut img, x0.max(2), y, x1.min(45), y, PLASTER_MID);
        }
    }
    // One glazing bar down each slope, parallel to it.
    for step in 0..5 {
        draw::put(&mut img, 19 - step, 8 + step * 2, PLASTER_MID);
        draw::put(&mut img, 20 - step, 8 + step * 2, PLASTER_DARK);
        draw::put(&mut img, 28 + step, 8 + step * 2, PLASTER_MID);
        draw::put(&mut img, 29 + step, 9 + step * 2, PLASTER_DARK);
    }
    draw::hline(&mut img, 2, 45, 20, PLASTER_MID);
    draw::hline(&mut img, 22, 25, 4, FOAM);
    // The walls: glass in a white frame, with the beds behind it.
    rect(&mut img, 4, 21, 43, 41, WATER_SHALLOW);
    draw::hline(&mut img, 5, 42, 22, FOAM);
    for x in (6..43).step_by(6) {
        draw::vline(&mut img, x, 21, 41, PLASTER_MID);
        draw::vline(&mut img, x + 1, 21, 41, FOAM);
    }
    draw::hline(&mut img, 4, 43, 32, PLASTER_MID);
    draw::hline(&mut img, 4, 43, 33, PLASTER_DARK);
    draw::hline(&mut img, 4, 43, 41, WATER_MID);
    // The beds: two rows of green, seen through the glass.
    for x in 6..42 {
        if (x / 3) % 2 == 0 {
            draw::put(&mut img, x, 36, LEAF_MID);
            draw::put(&mut img, x, 37, LEAF_DARK);
        }
        if (x / 4) % 2 == 0 {
            draw::put(&mut img, x, 28, LEAF_MID);
            draw::put(&mut img, x, 29, LEAF_DARK);
        }
    }
    // The door.
    rect(&mut img, 19, 26, 28, 41, PLASTER_MID);
    rect(&mut img, 20, 27, 27, 41, WATER_SHALLOW);
    draw::hline(&mut img, 20, 27, 27, FOAM);
    draw::vline(&mut img, 23, 27, 41, PLASTER_MID);
    draw::put(&mut img, 26, 35, GOLD_MID);
    // The stone base.
    rect(&mut img, 3, 41, 44, 45, STONE_MID);
    draw::hline(&mut img, 3, 44, 41, STONE_LIGHT);
    draw::hline(&mut img, 3, 44, 45, STONE_DARK);
    for x in (6..44).step_by(7) {
        draw::vline(&mut img, x, 42, 45, STONE_DARK);
    }
    finish(&mut img);
    img
}

// --- characters ------------------------------------------------------------

/// The thirty-two character cells: two casts, four directions, four frames.
fn character_sprites() -> Vec<(String, Image)> {
    let mut sprites = Vec::with_capacity(CASTS.len() * DIRECTIONS.len() * FRAMES);
    for cast in CASTS {
        for direction in DIRECTIONS {
            for frame in 0..FRAMES {
                if let Some(image) = character(cast, direction, frame) {
                    sprites.push((format!("{cast}_{direction}_{frame}"), image));
                }
            }
        }
    }
    sprites
}

/// One character cell, or `None` for an unknown cast or direction.
///
/// Frame 0 stands still, frames 1 and 3 are the two contacts of a step — the
/// left leg leading and then the right — and frame 2 is the pass between them,
/// where the feet come together and the body rises a pixel. Frames 1 and 3 are
/// mirror images of each other's legs, which is what makes the cycle read as
/// walking rather than as a shuffle.
#[must_use]
pub fn character(cast: &str, direction: &str, frame: usize) -> Option<Image> {
    if !DIRECTIONS.contains(&direction) || frame >= FRAMES {
        return None;
    }
    let player = cast == "player";
    if !player && cast != "villager" {
        return None;
    }
    let profile = direction == "left" || direction == "right";
    let back = direction == "up";
    // The pass is the frame the body rises on; the contacts stay planted.
    let bob = if frame == 2 { -1 } else { 0 };
    // Which leg leads: +1 the near leg, -1 the far one, 0 neither.
    let step = match frame {
        1 => 1,
        3 => -1,
        _ => 0,
    };

    let mut img = Image::transparent(CHAR_W, CHAR_H);
    draw_legs(&mut img, player, profile, step);
    draw_torso(&mut img, player, profile, step, bob);
    draw_head(&mut img, player, profile, back, bob);
    finish(&mut img);
    // The right-facing frames are the left-facing ones mirrored, so the two
    // profiles cannot drift apart. The figure is shaded from directly above for
    // exactly this reason: a mirror is invisible on a top-lit shape.
    Some(if direction == "right" {
        img.flip_x()
    } else {
        img
    })
}

/// Legs and boots.
///
/// `step` is +1 when the near leg leads, -1 when the far one does, and 0 for
/// the standing and passing frames. In profile a leading leg swings clear of
/// the hip; from the front and back it swings out to its own side, which is the
/// same motion seen from a different seat.
fn draw_legs(img: &mut Image, player: bool, profile: bool, step: i32) {
    let (trousers, light) = if player {
        (OVERALL_MID, OVERALL_LIGHT)
    } else {
        (TROUSER_MID, TROUSER_LIGHT)
    };
    // `(x, lift)` per leg. The far leg is drawn first and in a darker cloth, so
    // the near one overlaps it and the stride reads as depth rather than as two
    // legs side by side. The contacts swing a leg two pixels clear of the hip,
    // which is the smallest displacement that still reads as a step at 1x.
    let (far, near) = if profile {
        match step {
            1 => ((11, 0), (4, 0)),
            -1 => ((4, 0), (11, 0)),
            _ => ((6, 1), (8, 0)),
        }
    } else {
        match step {
            1 => ((3, 0), (10, 0)),
            -1 => ((5, 0), (12, 0)),
            _ => ((6, 1), (9, 0)),
        }
    };
    let far_cloth = if player { OVERALL_DARK } else { TROUSER_MID };
    leg(img, far.0, far.1, far_cloth, far_cloth);
    leg(img, near.0, near.1, trousers, light);
}

/// One leg: a two-pixel trouser column from the hip to the ankle, a boot below
/// it, and the one-pixel lift that turns a planted foot into a stepping one.
fn leg(img: &mut Image, x: i32, lift: i32, trousers: Color8, light: Color8) {
    let hip = 19;
    let ankle = 21 - lift;
    rect(img, x, hip, x + 1, ankle, trousers);
    draw::vline(img, x, hip, ankle, light);
    draw::hline(img, x - 1, x + 2, ankle + 1, DIRT_DARK);
    draw::hline(img, x, x + 1, ankle + 2, DIRT_DARK);
    draw::put(img, x + 2, ankle + 2, SHADOW);
}

/// The torso: shirt, overalls or trousers, and two arms that swing opposite the
/// legs.
fn draw_torso(img: &mut Image, player: bool, profile: bool, step: i32, bob: i32) {
    let top = 12 + bob;
    let bottom = 18 + bob;
    let shirt = if player { SHIRT_CREAM } else { VILLAGER_MID };
    let shirt_dark = if player { PLASTER_DARK } else { VILLAGER_DARK };
    // Shoulders first, so the head sits on a body that is wider than it.
    rect(img, 4, top, 11, top + 1, shirt);
    draw::hline(img, 4, 11, top, if player { FOAM } else { GRASS_LIGHT });
    rect(img, 5, top, 10, bottom, shirt);
    draw::vline(img, 10, top, bottom, shirt_dark);

    if player {
        // Overalls: a bib, two straps over the shoulders, and a pocket.
        rect(img, 5, top + 3, 10, bottom, OVERALL_MID);
        draw::vline(img, 5, top + 3, bottom, OVERALL_LIGHT);
        draw::vline(img, 10, top + 3, bottom, OVERALL_DARK);
        draw::vline(img, 6, top + 1, top + 3, OVERALL_MID);
        draw::vline(img, 9, top + 1, top + 3, OVERALL_DARK);
        draw::hline(img, 5, 10, top + 3, OVERALL_LIGHT);
        draw::put(img, 6, top + 3, GOLD_MID);
        draw::put(img, 9, top + 3, GOLD_MID);
        draw::hline(img, 7, 8, top + 5, OVERALL_DARK);
        draw::put(img, 7, top + 6, OVERALL_DARK);
        draw::put(img, 8, top + 6, OVERALL_DARK);
    } else {
        // A belt, and a buckle to catch the eye.
        draw::hline(img, 5, 10, bottom - 1, TROUSER_MID);
        draw::hline(img, 5, 10, bottom, TROUSER_LIGHT);
        draw::put(img, 7, bottom - 1, GOLD_MID);
        draw::put(img, 8, bottom - 1, GOLD_MID);
    }

    // Arms. In profile only the near one is drawn, swinging fore and aft with
    // the step; from the front and back both are drawn and the swing is a
    // one-pixel drop instead, which is the same motion seen from another seat.
    let swing = if step > 0 { 1 } else { 0 };
    if profile {
        let x = 7 + step;
        let arm_top = top + 1;
        rect(img, x, arm_top, x + 1, arm_top + 3, shirt);
        draw::put(img, x, arm_top + 4, SKIN_MID);
        draw::put(img, x + 1, arm_top + 4, SKIN_MID);
        draw::put(img, x, arm_top + 3, SKIN_DARK);
        draw::vline(
            img,
            x,
            arm_top,
            arm_top + 3,
            if player { FOAM } else { GRASS_LIGHT },
        );
        draw::vline(img, x + 1, arm_top, arm_top + 3, shirt_dark);
    } else {
        for (x, offset) in [(3, swing), (11, 1 - swing)] {
            let arm_top = top + 1 + offset;
            rect(img, x, arm_top, x + 1, arm_top + 3, shirt);
            draw::put(img, x, arm_top + 4, SKIN_MID);
            draw::put(img, x + 1, arm_top + 4, SKIN_MID);
            draw::put(img, x, arm_top + 3, SKIN_DARK);
        }
        draw::vline(
            img,
            3,
            top + 2,
            top + 4,
            if player { FOAM } else { GRASS_LIGHT },
        );
        draw::vline(img, 12, top + 2, top + 4, shirt_dark);
    }
}

/// The head: hair, face and the player's straw hat.
///
/// The four directions are told apart by the face and nothing else — two eyes
/// down, a nose and one eye in profile, the back of the head up — because at
/// this size the body carries almost no information.
fn draw_head(img: &mut Image, player: bool, profile: bool, back: bool, bob: i32) {
    let top = 5 + bob;
    let hair = if player { HAIR_MID } else { HAIR_DARK };
    let hair_light = if player { HAIR_DARK } else { HAIR_MID };
    let skin = SKIN_MID;
    rect(img, 5, top, 10, top + 6, skin);
    draw::vline(img, 10, top, top + 6, SKIN_DARK);
    draw::hline(img, 5, 10, top + 6, SKIN_DARK);

    if back {
        // The back of the head is all hair, with a lit crown.
        rect(img, 5, top, 10, top + 5, hair);
        draw::hline(img, 6, 9, top, hair_light);
        draw::put(img, 6, top + 1, hair_light);
        draw::vline(img, 5, top + 1, top + 4, hair_light);
        draw::hline(img, 6, 9, top + 6, hair_light);
    } else if profile {
        // Facing left: hair over the crown and down the back of the skull, one
        // eye, and a nose that breaks the silhouette.
        rect(img, 8, top, 10, top + 5, hair);
        draw::hline(img, 5, 10, top, hair);
        draw::put(img, 7, top + 1, hair_light);
        draw::put(img, 6, top + 1, skin);
        draw::put(img, 5, top + 2, skin);
        draw::put(img, 4, top + 3, skin);
        draw::put(img, 4, top + 4, SKIN_DARK);
        draw::put(img, 6, top + 3, SHADOW);
        draw::put(img, 5, top + 5, SKIN_DARK);
        draw::put(img, 6, top + 5, SKIN_DARK);
    } else {
        // A fringe, two eyes and a mouth.
        rect(img, 5, top, 10, top + 1, hair);
        draw::hline(img, 6, 9, top, hair_light);
        draw::put(img, 5, top + 2, hair);
        draw::put(img, 10, top + 2, hair);
        draw::put(img, 6, top + 3, SHADOW);
        draw::put(img, 9, top + 3, SHADOW);
        draw::put(img, 6, top + 2, SKIN_DARK);
        draw::hline(img, 7, 8, top + 5, SKIN_DARK);
    }

    if player {
        // A straw hat: a two-pixel crown, a brim that overhangs it by three
        // pixels a side, and a dark band where they meet.
        rect(img, 5, top - 4, 10, top - 2, STRAW_MID);
        draw::hline(img, 5, 10, top - 4, SAND_LIGHT);
        draw::vline(img, 5, top - 4, top - 2, SAND_LIGHT);
        draw::vline(img, 10, top - 3, top - 2, STRAW_DARK);
        rect(img, 2, top - 1, 13, top - 1, STRAW_MID);
        draw::hline(img, 2, 13, top - 1, STRAW_DARK);
        draw::put(img, 2, top - 2, STRAW_DARK);
        draw::put(img, 13, top - 2, STRAW_DARK);
        draw::put(img, 3, top - 1, STRAW_DARK);
        draw::put(img, 12, top - 1, STRAW_DARK);
    } else {
        // The villager's hair, swept back over the ears.
        draw::put(img, 4, top + 1, hair);
        draw::put(img, 11, top + 1, hair);
        draw::vline(img, 4, top + 2, top + 3, hair);
        draw::vline(img, 11, top + 2, top + 3, hair);
    }
}

// --- ui --------------------------------------------------------------------

/// Every UI region, in sheet order: nine nine-slices, then the icons.
fn ui_sprites() -> Vec<(String, Image)> {
    let mut sprites = Vec::new();
    for name in NINE_SLICE_NAMES {
        if let Some(image) = nine_slice(name) {
            sprites.push((name.to_string(), image));
        }
    }
    for name in TOOL_ICON_NAMES
        .iter()
        .chain(WEATHER_ICON_NAMES.iter())
        .chain(MISC_ICON_NAMES.iter())
        .chain(ITEM_ICON_NAMES.iter())
        .chain(SEED_ICON_NAMES.iter())
    {
        if let Some(image) = icon(name) {
            sprites.push(((*name).to_string(), image));
        }
    }
    sprites
}

/// One nine-slice source by name.
///
/// Every one of these is a 16x16 cell with a 4-pixel border, which is the
/// smallest border that gives `Insets::all(4)` a corner block, an edge run and
/// a centre to stretch independently. The edge runs are flat on purpose: a
/// dithered edge would smear into a visible band when the middle of a panel is
/// stretched, so all of the detail lives in the corners.
#[must_use]
pub fn nine_slice(name: &str) -> Option<Image> {
    let image = match name {
        "panel" => panel(
            UI_EDGE,
            UI_WOOD_LIGHT,
            UI_WOOD_MID,
            UI_WOOD_DARK,
            UI_WOOD_MID,
        ),
        "panel_dark" => panel(UI_EDGE, UI_DARK_LIGHT, UI_DARK_MID, UI_DEEP, UI_DARK_MID),
        "panel_light" => panel(
            UI_WOOD_DARK,
            UI_PALE_LIGHT,
            UI_PALE_MID,
            UI_PALE_DARK,
            UI_PALE_MID,
        ),
        // The three button states have to be told apart at a glance, so they
        // differ in fill as well as in bevel: raised and pale, lit up, and
        // pushed in and gone dark.
        "button" => panel(
            UI_EDGE,
            UI_PALE_LIGHT,
            UI_PALE_MID,
            UI_PALE_DARK,
            UI_PALE_DARK,
        ),
        "button_hover" => panel(UI_EDGE, FOAM, UI_PALE_LIGHT, UI_PALE_MID, GOLD_DARK),
        "button_press" => panel(
            UI_EDGE,
            UI_WOOD_DARK,
            UI_WOOD_MID,
            UI_PALE_MID,
            UI_WOOD_DARK,
        ),
        "slot" => panel(UI_EDGE, UI_WOOD_DARK, UI_WELL, UI_WOOD_MID, UI_WELL),
        "slot_selected" => panel(UI_EDGE, GOLD_LIGHT, UI_WELL, GOLD_DARK, UI_WELL),
        "tooltip" => panel(SHADOW, FOAM, PLASTER_MID, PLASTER_DARK, PLASTER_MID),
        _ => return None,
    };
    Some(image)
}

/// The nine-slice body: an outline ring, a bevelled second ring, a flat centre
/// and a one-pixel corner cut.
fn panel(edge: Color8, light: Color8, fill: Color8, shade: Color8, inner: Color8) -> Image {
    let mut img = Image::new(TILE, TILE, fill);
    draw::frame(&mut img, Area::new(0, 0, 15, 15), edge);
    draw::hline(&mut img, 1, 14, 1, light);
    draw::vline(&mut img, 1, 1, 14, light);
    draw::hline(&mut img, 1, 14, 14, shade);
    draw::vline(&mut img, 14, 1, 14, shade);
    draw::frame(&mut img, Area::new(2, 2, 13, 13), inner);
    // The corner cut lives entirely inside the 4-pixel corner block, so the
    // edge runs the nine-slice stretches stay exactly flat.
    round(&mut img, 0, 0, 15, 15, 2);
    img
}

/// The stencil alphabet, shared by every hand-laid icon.
///
/// One character per colour: a bitmap says "this particular arrangement of a
/// dozen pixels is a hoe" far more directly than three lines and an ellipse do,
/// and it cannot come out antialiased. `.` is nothing; everything else is a
/// colour, and every colour here is in [`PALETTE`].
const STENCIL_KEY: [(char, Color8); 26] = [
    ('s', SHADOW),
    ('o', STONE_LIGHT),
    ('x', STONE_MID),
    ('X', STONE_DARK),
    ('w', DIRT_LIGHT),
    ('W', DIRT_MID),
    ('v', DIRT_DARK),
    ('y', GOLD_MID),
    ('Y', GOLD_LIGHT),
    ('z', GOLD_DARK),
    ('g', LEAF_MID),
    ('G', GRASS_LIGHT),
    ('h', LEAF_DARK),
    ('m', GRASS_MID),
    ('r', TOMATO_MID),
    ('R', TOMATO_LIGHT),
    ('e', TOMATO_DARK),
    ('b', WATER_SHALLOW),
    ('B', WATER_MID),
    ('f', FOAM),
    ('p', PLASTER_MID),
    ('P', PLASTER_DARK),
    ('k', SKIN_MID),
    ('u', UI_PALE_MID),
    ('c', CAULI_MID),
    ('C', CAULI_LIGHT),
];

/// Paints a stencil with its top-left corner at `(x, y)`.
fn stencil(img: &mut Image, x: i32, y: i32, art: &[&str]) {
    for (row, line) in art.iter().enumerate() {
        for (col, symbol) in line.chars().enumerate() {
            if let Some((_, color)) = STENCIL_KEY.iter().find(|(key, _)| *key == symbol) {
                draw::put(img, x + col as i32, y + row as i32, *color);
            }
        }
    }
}

