/// One icon by name.
///
/// The tools, the star, the heart, the bolt and the shipping bin are hand-laid
/// stencils; the weather, the coin, the clock and the produce are drawn from
/// primitives, which is shorter wherever the shape really is geometric. Every
/// icon is finished with the house outline, so an icon reads the same on a dark
/// panel and on parchment.
#[must_use]
pub fn icon(name: &str) -> Option<Image> {
    let mut img = Image::transparent(TILE, TILE);
    match name {
        "icon_hoe" => stencil(&mut img, 0, 0, ICON_HOE),
        "icon_axe" => stencil(&mut img, 0, 0, ICON_AXE),
        "icon_pickaxe" => stencil(&mut img, 0, 0, ICON_PICKAXE),
        "icon_scythe" => stencil(&mut img, 0, 0, ICON_SCYTHE),
        "icon_star" => stencil(&mut img, 0, 0, ICON_STAR),
        "icon_heart" => stencil(&mut img, 0, 0, ICON_HEART),
        "icon_energy" => stencil(&mut img, 0, 0, ICON_BOLT),
        "icon_shipping" => stencil(&mut img, 0, 0, ICON_SHIPPING),
        "icon_can" => watering_can(&mut img),
        "icon_sun" => {
            disc(&mut img, 8, 8, 4, GOLD_MID);
            disc(&mut img, 7, 7, 2, GOLD_LIGHT);
            draw::put(&mut img, 11, 11, GOLD_DARK);
            draw::hline(&mut img, 7, 8, 1, GOLD_MID);
            draw::hline(&mut img, 7, 8, 14, GOLD_MID);
            draw::vline(&mut img, 1, 7, 8, GOLD_MID);
            draw::vline(&mut img, 14, 7, 8, GOLD_MID);
            for (x, y) in [(3, 3), (12, 3), (3, 12), (12, 12)] {
                draw::put(&mut img, x, y, GOLD_LIGHT);
                draw::put(&mut img, x + 1, y, GOLD_MID);
            }
        }
        "icon_cloud" => cloud(&mut img, 8, 7, FOAM, PLASTER_MID),
        "icon_rain" => {
            cloud(&mut img, 8, 5, FOAM, PLASTER_MID);
            for x in [3, 6, 9, 12] {
                draw::put(&mut img, x, 11, WATER_SHALLOW);
                draw::put(&mut img, x, 12, WATER_MID);
                draw::put(&mut img, x, 13, WATER_SHALLOW);
            }
        }
        "icon_storm" => {
            cloud(&mut img, 8, 5, STONE_LIGHT, STONE_MID);
            draw::put(&mut img, 3, 5, FOAM);
            stencil(&mut img, 6, 10, ICON_BOLT_SMALL);
        }
        "icon_snow" => snowflake(&mut img),
        "icon_coin" => coin(&mut img),
        "icon_clock" => clock(&mut img),
        "icon_calendar" => calendar(&mut img),
        "icon_bag" => bag(&mut img),
        "icon_seed" => seed_packet(&mut img, LEAF_MID, GRASS_LIGHT),
        "icon_water" => droplet(&mut img),
        "item_parsnip" => item_parsnip(&mut img),
        "item_cauliflower" => item_cauliflower(&mut img),
        "item_potato" => item_potato(&mut img),
        "item_tomato" => item_tomato(&mut img),
        "item_corn" => item_corn(&mut img),
        "item_pumpkin" => item_pumpkin(&mut img),
        "seed_parsnip" => seed_packet(&mut img, PARSNIP_MID, CAULI_LIGHT),
        "seed_cauliflower" => seed_packet(&mut img, CAULI_MID, CAULI_LIGHT),
        "seed_potato" => seed_packet(&mut img, POTATO_MID, POTATO_DARK),
        "seed_tomato" => seed_packet(&mut img, TOMATO_MID, TOMATO_LIGHT),
        "seed_corn" => seed_packet(&mut img, CORN_MID, CORN_LIGHT),
        "seed_pumpkin" => seed_packet(&mut img, PUMPKIN_MID, PUMPKIN_LIGHT),
        _ => return None,
    }
    finish(&mut img);
    Some(img)
}

/// A watering can: a can body, a hoop handle and a spout with water coming out
/// of it. The spout is what tells it apart from every other metal tool.
fn watering_can(img: &mut Image) {
    // The body, with a rim.
    rect(img, 5, 8, 12, 13, STONE_MID);
    draw::hline(img, 5, 12, 8, STONE_LIGHT);
    draw::vline(img, 5, 8, 13, STONE_LIGHT);
    draw::hline(img, 5, 12, 13, STONE_DARK);
    draw::vline(img, 12, 8, 13, STONE_DARK);
    draw::put(img, 6, 10, STONE_LIGHT);
    draw::put(img, 6, 11, STONE_LIGHT);
    // The hoop handle over the top.
    for (x, y) in [(6, 7), (7, 6), (8, 5), (9, 5), (10, 6), (11, 7)] {
        draw::put(img, x, y, STONE_DARK);
        draw::put(img, x, y + 1, STONE_MID);
    }
    // The spout, flaring at the mouth.
    for step in 0..4 {
        let (x, y) = (4 - step, 8 - step);
        draw::put(img, x, y, STONE_MID);
        draw::put(img, x, y + 1, STONE_LIGHT);
    }
    draw::put(img, 1, 4, STONE_LIGHT);
    draw::put(img, 1, 5, STONE_MID);
    draw::put(img, 0, 5, STONE_MID);
    // Water leaving the spout.
    draw::put(img, 1, 7, WATER_SHALLOW);
    draw::put(img, 2, 8, WATER_SHALLOW);
    draw::put(img, 2, 9, WATER_MID);
}

/// A snowflake: six spokes off one hub, which is unmistakably not rain.
fn snowflake(img: &mut Image) {
    draw::hline(img, 2, 13, 8, FOAM);
    draw::vline(img, 8, 2, 13, FOAM);
    for step in 0..6 {
        let d = step + 1;
        draw::put(img, 8 + d, 8 - d, WATER_SHALLOW);
        draw::put(img, 8 - d, 8 - d, WATER_SHALLOW);
        draw::put(img, 8 + d, 8 + d, WATER_SHALLOW);
        draw::put(img, 8 - d, 8 + d, WATER_SHALLOW);
    }
    for d in [3, 5] {
        draw::put(img, 8 + d, 8 - d + 1, FOAM);
        draw::put(img, 8 - d, 8 - d + 1, FOAM);
        draw::put(img, 8 + d, 8 + d - 1, FOAM);
        draw::put(img, 8 - d, 8 + d - 1, FOAM);
    }
    disc(img, 8, 8, 1, FOAM);
}

/// A coin: a milled disc with a lit rim.
fn coin(img: &mut Image) {
    disc(img, 8, 8, 6, GOLD_MID);
    disc(img, 8, 8, 4, GOLD_DARK);
    disc(img, 8, 8, 3, GOLD_MID);
    for (x, y) in [(6, 5), (7, 5), (5, 6), (5, 7)] {
        draw::put(img, x, y, GOLD_LIGHT);
    }
    draw::put(img, 11, 11, GOLD_DARK);
    draw::hline(img, 7, 8, 6, GOLD_LIGHT);
}

/// A clock: a dark rim, a pale face, two hands.
fn clock(img: &mut Image) {
    disc(img, 8, 8, 6, STONE_MID);
    disc(img, 8, 8, 5, STONE_LIGHT);
    disc(img, 8, 8, 4, FOAM);
    draw::vline(img, 8, 5, 8, SHADOW);
    draw::hline(img, 8, 11, 8, SHADOW);
    draw::put(img, 9, 9, SHADOW);
    draw::put(img, 5, 4, FOAM);
    draw::put(img, 11, 12, STONE_DARK);
}

/// A calendar: a red head, two rings and a page of days.
fn calendar(img: &mut Image) {
    rect(img, 2, 3, 13, 13, FOAM);
    draw::frame(img, Area::new(2, 3, 13, 13), PLASTER_DARK);
    rect(img, 2, 3, 13, 6, ROOF_RED);
    draw::hline(img, 2, 13, 3, ROOF_LIGHT);
    draw::hline(img, 2, 13, 6, ROOF_DARK);
    for x in [5, 10] {
        draw::vline(img, x, 1, 3, STONE_MID);
        draw::put(img, x, 1, STONE_LIGHT);
    }
    for row in 0..2 {
        for col in 0..3i32 {
            draw::put(img, 4 + col * 3, 8 + row * 3, PLASTER_DARK);
            draw::put(img, 5 + col * 3, 8 + row * 3, PLASTER_DARK);
        }
    }
}

/// A satchel: a flap, a body and a buckle.
fn bag(img: &mut Image) {
    rect(img, 3, 6, 12, 13, DIRT_MID);
    draw::hline(img, 3, 12, 6, DIRT_LIGHT);
    draw::hline(img, 3, 12, 13, DIRT_DARK);
    draw::vline(img, 3, 6, 13, DIRT_LIGHT);
    draw::vline(img, 12, 6, 13, DIRT_DARK);
    rect(img, 3, 5, 12, 9, DIRT_LIGHT);
    draw::hline(img, 3, 12, 9, DIRT_DARK);
    draw::hline(img, 3, 12, 5, SAND_LIGHT);
    rect(img, 7, 9, 8, 10, GOLD_MID);
    draw::put(img, 7, 9, GOLD_LIGHT);
    for (x, y) in [(5, 4), (10, 4), (4, 5), (11, 5)] {
        draw::put(img, x, y, DIRT_DARK);
    }
}

/// A drop of water.
fn droplet(img: &mut Image) {
    draw::put(img, 8, 1, WATER_SHALLOW);
    for step in 0..4 {
        draw::hline(img, 8 - step - 1, 8 + step, 2 + step, WATER_SHALLOW);
    }
    disc(img, 8, 10, 5, WATER_SHALLOW);
    draw::hline(img, 4, 11, 13, WATER_MID);
    draw::hline(img, 5, 10, 14, WATER_MID);
    draw::put(img, 6, 8, FOAM);
    draw::put(img, 5, 9, FOAM);
    draw::put(img, 11, 12, WATER_DEEP);
}

/// A parsnip: a long cream root under a fan of leaves.
fn item_parsnip(img: &mut Image) {
    for y in 4..15 {
        let half = if y < 6 { 2 } else { 2 + (y - 6) / 4 };
        rect(img, 8 - half, y, 7 + half, y, PARSNIP_MID);
        draw::put(img, 7 + half, y, PARSNIP_DARK);
        draw::put(img, 8 - half, y, CAULI_LIGHT);
    }
    draw::hline(img, 6, 9, 14, PARSNIP_DARK);
    for (x, y, dx, dy) in [(8, 4, -1, -1), (8, 4, 1, -1), (7, 3, -1, -1), (9, 3, 1, -1)] {
        leaf(img, x, y, dx, dy, 3);
    }
    draw::vline(img, 8, 4, 6, LEAF_DARK);
}

/// A cauliflower: a white curd wrapped in leaves.
fn item_cauliflower(img: &mut Image) {
    disc(img, 8, 7, 5, CAULI_MID);
    disc(img, 6, 5, 3, CAULI_LIGHT);
    draw::put(img, 12, 9, CAULI_DARK);
    draw::put(img, 11, 10, CAULI_DARK);
    draw::hline(img, 4, 11, 12, CAULI_DARK);
    for (x, y, dx) in [(8, 12, -1), (8, 12, 1), (8, 11, -2), (8, 11, 2)] {
        leaf(img, x, y, dx, 1, 3);
    }
    draw::hline(img, 3, 12, 15, LEAF_DARK);
}

/// A potato: a knobbly tan tuber with eyes.
fn item_potato(img: &mut Image) {
    oval(img, 8, 9, 6, 5, POTATO_MID);
    oval(img, 5, 6, 3, 2, POTATO_MID);
    draw::hline(img, 3, 12, 14, POTATO_DARK);
    draw::hline(img, 4, 11, 13, POTATO_DARK);
    for (x, y) in [(5, 7), (9, 6), (7, 11), (11, 10), (8, 8)] {
        draw::put(img, x, y, POTATO_DARK);
    }
    draw::put(img, 6, 5, SAND_LIGHT);
    draw::put(img, 7, 5, SAND_LIGHT);
    draw::put(img, 4, 8, SAND_LIGHT);
}

/// A tomato: a red fruit with a green calyx.
fn item_tomato(img: &mut Image) {
    disc(img, 8, 9, 5, TOMATO_MID);
    draw::hline(img, 5, 12, 13, TOMATO_DARK);
    draw::put(img, 12, 12, TOMATO_DARK);
    draw::put(img, 5, 6, TOMATO_LIGHT);
    draw::put(img, 6, 5, TOMATO_LIGHT);
    draw::put(img, 7, 5, TOMATO_LIGHT);
    for (x, y) in [(8, 3), (7, 4), (9, 4), (6, 5), (10, 5)] {
        draw::put(img, x, y, LEAF_MID);
    }
    draw::put(img, 8, 2, LEAF_DARK);
}

/// A cob of maize: a yellow cob in its husk.
fn item_corn(img: &mut Image) {
    for y in 2..15 {
        let half = 3 + (y % 3 == 0) as i32;
        rect(img, 8 - half, y, 7 + half, y, CORN_MID);
        draw::put(img, 8 - half, y, CORN_LIGHT);
        draw::put(img, 7 + half, y, CORN_DARK);
        if y % 2 == 0 {
            draw::put(img, 8, y, CORN_LIGHT);
            draw::put(img, 6, y, CORN_DARK);
            draw::put(img, 10, y, CORN_LIGHT);
        }
    }
    for (x, y, dx, dy) in [(2, 4, 1, 1), (13, 4, -1, 1), (2, 9, 1, 1), (13, 9, -1, 1)] {
        leaf(img, x, y, dx, dy, 5);
    }
    draw::put(img, 8, 1, CORN_LIGHT);
}

/// A pumpkin: a ribbed orange fruit under a green stalk.
fn item_pumpkin(img: &mut Image) {
    oval(img, 8, 10, 6, 5, PUMPKIN_MID);
    for rib in [-3, 0, 3] {
        let x = 8 + rib;
        for y in 6..=15 {
            let dy = y - 10;
            if rib * rib * 25 + dy * dy * 36 <= 36 * 25 {
                let color = if rib == -3 {
                    PUMPKIN_LIGHT
                } else {
                    PUMPKIN_DARK
                };
                draw::put(img, x, y, color);
            }
        }
    }
    draw::put(img, 5, 7, PUMPKIN_LIGHT);
    draw::put(img, 6, 6, PUMPKIN_LIGHT);
    draw::hline(img, 6, 9, 15, PUMPKIN_DARK);
    draw::put(img, 8, 4, LEAF_DARK);
    draw::put(img, 8, 3, GRASS_DARK);
    draw::put(img, 9, 3, GRASS_DARK);
}

/// A cloud: three overlapping puffs over a flat base.
fn cloud(img: &mut Image, cx: i32, cy: i32, top: Color8, base: Color8) {
    disc(img, cx - 3, cy, 3, base);
    disc(img, cx + 1, cy - 1, 4, base);
    disc(img, cx + 4, cy + 1, 2, base);
    rect(img, cx - 6, cy + 1, cx + 6, cy + 3, base);
    disc(img, cx - 3, cy - 1, 2, top);
    disc(img, cx + 1, cy - 2, 3, top);
    rect(img, cx - 5, cy + 1, cx + 5, cy + 1, top);
    draw::hline(img, cx - 6, cx + 6, cy + 4, STONE_DARK);
}

/// A seed packet: a paper envelope with a folded top and a coloured band.
fn seed_packet(img: &mut Image, band: Color8, light: Color8) {
    rect(img, 3, 3, 12, 14, PLASTER_MID);
    draw::frame(img, Area::new(3, 3, 12, 14), PLASTER_DARK);
    draw::hline(img, 3, 12, 3, FOAM);
    // The fold at the top.
    draw::hline(img, 3, 12, 5, PLASTER_DARK);
    draw::hline(img, 3, 12, 4, FOAM);
    // The band carrying the crop's colour.
    rect(img, 4, 7, 11, 10, band);
    draw::hline(img, 4, 11, 7, light);
    draw::hline(img, 4, 11, 10, PLASTER_DARK);
    // A sprout on the packet, so it reads as seed rather than as an envelope.
    draw::vline(img, 8, 11, 12, LEAF_DARK);
    draw::put(img, 7, 11, LEAF_MID);
    draw::put(img, 9, 11, LEAF_MID);
    draw::put(img, 7, 12, GRASS_LIGHT);
    draw::put(img, 9, 12, GRASS_LIGHT);
}

